export const OC_ROWS: OcRow[] = [["oc-albin-counter-gambit-01", "albin-counter-gambit", "Albin: 4.e3?! and Black's Initiative", "D08", "d4 d5 c4 e5 dxe5 d4 e3", 6, ["Nf3"], "b", ""], ["oc-albin-counter-gambit-02", "albin-counter-gambit", "Lasker Trap (Underpromotion to Knight)", "D08", "d4 d5 c4 e5 dxe5 d4 e3 Bb4 Bd2 dxe3 Bxb4 exf2 Ke2 fxg1=N Rxg1 Bg4 Ke1 Bxd1", 10, ["fxe3"], "b", "White sees that Black has 'hung' the bishop on b4: after 5...dxe3 it's en prise."], ["oc-albin-counter-gambit-03", "albin-counter-gambit", "Lasker Trap: the King Walk (8.Ke1)", "D08", "d4 d5 c4 e5 dxe5 d4 e3 Bb4 Bd2 dxe3 Bxb4 exf2 Ke2 fxg1=N Ke1 Qh4 g3 Qe4", 14, [], "b", "The same trap, one branch deeper. After 7...fxg1=N+ Black is a knight up on g1."], ["oc-albin-counter-gambit-04", "albin-counter-gambit", "Albin: 4.Ne5? The Knight Has No Square", "D08", "d4 d5 c4 e5 Nf3 e4 Ne5 f6 Ng4 Bxg4", 6, ["Nfd2"], "w", "Kicked once by 3...e4, the knight jumps to the most central square it sees."], ["oc-albin-counter-gambit-05", "albin-counter-gambit", "Albin: 8.Kxf2?? The King Stops Guarding d1", "D08", "d4 d5 c4 e5 dxe5 d4 Nf3 Nc6 e3 Bb4 Bd2 dxe3 Bxb4 exf2 Kxf2 Qxd1", 14, [], "w", ""], ["oc-alekhine-defense-01", "alekhine-defense", "Alekhine: Qh5/Bh6/Bxf8 Exchange", "B02", "e4 Nf6 e5 Nd5 d4 d6 Bc4 Nb6 Bb3 dxe5 Qh5 e6 dxe5 Be7 Qg4 O-O", 15, ["g5"], "w", "White's queen and bishop aim at g7. After 8...O-O, Bh6 forces ...g6 and Bxf8 wins the exchange. 8...g5! closes the c1-h6 diagonal."], ["oc-alekhine-defense-02", "alekhine-defense", "Alekhine: 9.d6?? Qh4+ and the h1-rook falls", "B03", "e4 Nf6 e5 Nd5 d4 d6 f4 dxe5 fxe5 c5 c4 Nb4 d5 Bf5 Na3 e6 d6 Qh4 g3 Qe4 Qe2 Qxh1 Be3 Nd3 Kd2 Nxe5 Bg2 Qxh2", 16, ["Nf3"], "b", "White pushes d6 while the king is exposed. After 9...Qh4+ and 10...Qe4+, the queen forks the king and the h1-rook. 9.Nf3 is safer."], ["oc-alekhine-defense-03", "alekhine-defense", "Alekhine: 10.Bb5?? Qa5+ and the bishop falls", "B02", "e4 Nf6 e5 Nd5 c4 Nb6 c5 Nd5 Nc3 e6 Nxd5 exd5 d4 d6 cxd6 cxd6 Nf3 Nc6 Bb5 Qa5 Bd2 Qxb5 exd6 Bxd6 a4 Qd3 Qe2 Qxe2", 18, ["Bd3", "a3", "Be2"], "b", "Bb5 pins the c6-knight, but b5 has no defender. ...Qa5+ checks the king and attacks the bishop."], ["oc-alekhine-defense-04", "alekhine-defense", "Alekhine: 14.b3?? Nexc4 opens the long diagonal", "B03", "e4 Nf6 e5 Nd5 d4 d6 exd6 cxd6 c4 Nb6 Nf3 g6 Nc3 Bg7 Bd3 Bg4 Be3 O-O h3 Bxf3 Qxf3 Nc6 d5 Ne5 Qe2 Rc8 b3 Nexc4 bxc4 Bxc3 Kd1 Bxa1 h4 Na4 Qc2 Nb2 Ke2 Nxd3", 26, ["c5", "Bxb6"], "b", "Defending c4 with b3 allows ...Nexc4, which removes the b2-pawn guarding c3 and opens the g7-bishop's diagonal."], ["oc-birds-opening-01", "birds-opening", "Bird's Opening: From's Gambit Bg3#", "A02", "f4 e5 fxe5 d6 exd6 Bxd6 Nf3 g5 h3 Bg3", 8, ["d4", "g3"], "b", "After 4...g5, 5.h3 leaves g3 undefended. Black mates with 5...Bg3. Instead 5.d4 or 5.g3 are sound."], ["oc-bishops-opening-01", "bishops-opening", "Bishop's Opening: after Qxg7, ...Rg8 loses", "C23", "e4 e5 Bc4 Nc6 Nc3 Bc5 Qg4 Nf6 Qxg7 Rg8 Qxf7", 9, ["Rf8"], "w", ""], ["oc-bishops-opening-02", "bishops-opening", "Bishop's Opening: 6...Nf2 forks, 7.Qh5! attacks", "C23", "e4 e5 Bc4 Bc5 Nc3 Nf6 d3 d6 f4 Ng4 f5 Nf2 Qh5 O-O Bg5 Qe8 Nd5 Qd7 Nf6 gxf6 Bxf6 Be3 Nh3 Nxh1 Qg4 Bg5 Qxg5", 11, ["g6"], "w", ""], ["oc-bishops-opening-03", "bishops-opening", "Bishop's Opening: the c6-knight leaves, Qb5+ wins a piece", "C24", "e4 e5 Bc4 Nf6 d3 Bc5 Nf3 Nc6 c3 d5 exd5 Nxd5 Qb3 Na5 Qb5 Nc6 Qxc5 Be6 Ng5 Nce7 Nxe6", 13, ["Nf6"], "w", ""], ["oc-budapest-gambit-01", "budapest-gambit", "Rubinstein Knight Grab (4.Bf4)", "A52", "d4 Nf6 c4 e5 dxe5 Ng4 Bf4 Bc5 e3 Nc6 Qxg4", 9, ["d6"], "w", "After 5.e3, Black's natural 5...Nc6 leaves the knight on g4 undefended. White's queen takes it along the open d1-g4 diagonal."], ["oc-budapest-gambit-02", "budapest-gambit", "Fajarowicz Trap", "A51", "d4 Nf6 c4 e5 dxe5 Ne4 a3 Nc6 Nf3 d6 exd6 Bxd6 g3 Nxf2 Kxf2 Bxg3 hxg3 Qxd1", 12, ["Nc3", "e3"], "b", "With the knight on e4 aimed at f2, 7.g3 allows a two-piece sacrifice: 7...Nxf2 forks queen and rook."], ["oc-budapest-gambit-03", "budapest-gambit", "Budapest Declined: 4.Bg5?? Runs Into ...Bxf2+", "A51", "d4 Nf6 c4 e5 d5 Bc5 Bg5 Bxf2 Kxf2 Ng4 Kg3 Qxg5 Nf3 Qf4 Kh3 Nf2", 6, ["Nc3"], "b", "The pin 4.Bg5 is unprotected. After 4...Bxf2+ 5.Kxf2 Ng4+ the knight opens the d8-h4 diagonal and the queen attacks the bishop."], ["oc-budapest-gambit-04", "budapest-gambit", "Budapest: 7.h3? The Kieninger Mate", "A52", "d4 Nf6 c4 e5 dxe5 Ng4 Bf4 Nc6 Nf3 Bb4 Nbd2 Qe7 h3 Ngxe5 Nxe5 Nxe5 a3 Nd3", 12, ["e3"], "b", "7.h3 pushes the knight away, but 7...Ngxe5 recovers the pawn with a mating threat. After the trades the king is boxed in by its own pieces."], ["oc-budapest-gambit-05", "budapest-gambit", "Budapest: 7.a3? The Bishop Was Never the Problem", "A52", "d4 Nf6 c4 e5 dxe5 Ng4 Bf4 Nc6 Nf3 Bb4 Nbd2 Qe7 a3 Ngxe5 Nxe5 Nxe5 axb4 Nd3", 12, ["e3"], "b", "7.a3 questions the bishop, but 7...Ngxe5 threatens ...Nd3 mate. After 9.axb4, Black mates with 9...Nd3."], ["oc-budapest-gambit-06", "budapest-gambit", "Budapest Adler: 14.Ne4? The Rook-Lift Was Aiming at h2", "A52", "d4 Nf6 c4 e5 dxe5 Ng4 Nf3 Bc5 e3 Nc6 Nc3 O-O Be2 Re8 O-O Ngxe5 a3 Nxf3 Bxf3 Ne5 Be2 a5 b3 Ra6 Bb2 Rh6 Ne4 Qh4 h3 Qxe4 Qd5 Qxd5", 26, ["h3"], "b", "Black's rook lift to h6 targets h2. After 14.Ne4 Qh4 the queen threatens mate on h2 and attacks the knight."], ["oc-blackmar-diemer-gambit-01", "blackmar-diemer-gambit", "Halosar Trap", "D00", "d4 d5 e4 dxe4 Nc3 Nf6 f3 exf3 Qxf3 Qxd4 Be3 Qb4 O-O-O Bg4 Nb5 Bxf3 Nxc7", 13, ["c6"], "w", "Black's natural 7...Bg4, attacking the queen, loses by force: 8.Nb5 threatens Nxc7 mate. Black should play 7...c6 first."], ["oc-caro-kann-alien-gambit-01", "caro-kann-alien-gambit", "Alien Gambit: 7...Bg4?? 8.Ne5+", "B15", "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Nf6 Ng5 h6 Nxf7 Kxf7 Nf3 Bg4", 13, ["c5"], "w", "After 7...Bg4, 8.Ne5+ forks king and bishop and White regains material. Black's better option is 7...c5."], ["oc-caro-kann-alien-gambit-02", "caro-kann-alien-gambit", "Alien Gambit: 13...Nd5? 14.Qe4", "B15", "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Nf6 Ng5 h6 Nxf7 Kxf7 Nf3 e6 Bd3 Bd6 O-O Rf8 Re1 Kg8 Ne5 Nbd7 Qf3 Nxe5 dxe5 Nd5 Qe4 Rf5 exd6", 25, ["Bc5"], "w", "13...Nd5 blocks but 14.Qe4 lines up on h7 and d5, and White wins back the piece. 13...Bc5 is stronger."], ["oc-caro-kann-alien-gambit-03", "caro-kann-alien-gambit", "Alien Gambit: 16...Qg8?? 17.Qf3+", "B15", "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Nf6 Ng5 h6 Nxf7 Kxf7 Nf3 e6 Bd3 Bd6 O-O Re8 Ne5 Bxe5 dxe5 Nd5 Qh5 Kg8 Bxh6 Qe7 Bg5 Qf7 Bh7 Kf8 Bg6 Qg8 Qf3 Nf6 exf6 gxf6 Qxf6 Qf7 Qxf7", 31, [], "w", "Black's pieces are overloaded: 17.Qf3+ forces ...Nf6 and the attack ends in mate on f7."], ["oc-caro-kann-alien-gambit-04", "caro-kann-alien-gambit", "Alien Gambit: 20...Nf4? 21.Rxf4", "B15", "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Nf6 Ng5 h6 Nxf7 Kxf7 Nf3 e6 Bd3 Bd6 O-O Rf8 Re1 Kg8 Ne5 Bxe5 dxe5 Nd5 Qg4 Qe8 Bxh6 Qf7 Bg6 Qxf2 Kh1 gxh6 Bd3 Kh8 Qg6 Qf7 Qxh6 Kg8 Re4 Nf4 Rxf4", 39, [], "w", "Black is up material but the king has lost its pawn cover; 21.Rxf4 keeps every White piece aimed at the king."], ["oc-caro-kann-martian-gambit-01", "caro-kann-martian-gambit", "Martian Gambit: 9...Nd7?? 10.Nxf7", "B18", "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Bf5 Ng5 Bg6 N1f3 h6 Ne6 fxe6 Ne5 Bf7 Bc4 Nd7", 17, ["Nf6"], "w", "After 9...Nd7, 10.Nxf7 wins the bishop with a fork on queen and rook."], ["oc-caro-kann-martian-gambit-02", "caro-kann-martian-gambit", "Martian Gambit: 9...Nf6?? 10.Bxe6 and 11.Bf7#", "B18", "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Bf5 Ng5 Bg6 N1f3 h6 Ne6 fxe6 Ne5 Bh7 Bc4 Nf6 Bxe6 Nbd7 Bf7", 17, ["Nd7"], "w", "After 9...Nf6, 10.Bxe6 leads to 11.Bf7 mate: the bishop is protected by the knight on e5 and Black's pieces block the escape squares."], ["oc-caro-kann-martian-gambit-03", "caro-kann-martian-gambit", "Martian Gambit: 11...Qb4+? 12.c3", "B18", "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Bf5 Ng5 Bg6 N1f3 e6 Ne5 Nf6 Bd3 Qxd4 Nxg6 hxg6 Nxf7 Bc5 Be3 Qb4 c3 Qxb2 Nxh8 Qxc3 Ke2 Bxe3 fxe3 Nbd7 Qb3 Qe5 Bxg6", 21, [], "w", "The check gains nothing: 12.c3 blocks with tempo and 13.Nxh8 wins the rook."], ["oc-caro-kann-martian-gambit-04", "caro-kann-martian-gambit", "Martian Gambit: 12...Ke8? 13.Nf7", "B18", "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Bf5 Ng5 Bg6 N1f3 h6 Ne6 fxe6 Ne5 Bh7 Bc4 Nf6 Bxe6 Qd6 Bf7 Kd8 Bb3 Ke8 Nf7 Qd7 Nxh8", 23, [], "w", "13.Nf7 attacks queen and rook at once, and White wins the rook on h8."], ["oc-caro-kann-martian-gambit-05", "caro-kann-martian-gambit", "Martian Gambit: 12...e6? 13.Nf7+", "B18", "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Bf5 Ng5 Bg6 N1f3 h6 Ne6 fxe6 Ne5 Bh7 Bc4 Nf6 Bxe6 Qd6 Bf7 Kd8 Bb3 e6 Nf7 Kc7 Nxd6", 23, [], "w", "13.Nf7+ forks king and queen and White wins the queen."], ["oc-center-game-01", "center-game", "Center Game: ...Qxe4?? Rd8+", "C22", "e4 e5 d4 exd4 Qxd4 Nc6 Qa4 Nf6 Nc3 d5 Bg5 dxe4 Nxe4 Qe7 O-O-O Qxe4", 15, ["Bd7"], "w", "Grabbing e4 allows the zwischenzug 9.Rd8+: the king is forced onto d8 and White wins the queen for a rook. 8...Bd7 is safe."], ["oc-center-game-02", "center-game", "Center Game: 6...Qf6?? 7.Nd5", "C22", "e4 e5 d4 exd4 Qxd4 Nc6 Qe3 b6 Nc3 Bc5 Qg3 Qf6 Nd5 Qe5 Nxc7 Qxc7 Qxc7", 11, ["Nf6"], "w", "7.Nd5 hits the queen and c7 at once. Fleeing to e5 allows a knight fork on c7. 6...Nf6 gives up only the g7 pawn."], ["oc-center-game-03", "center-game", "Center Game: 6...d6?? 7.Nd5", "C20", "e4 e5 d4 Nc6 dxe5 Nxe5 Nf3 Qf6 Nc3 Bb4 Bd2 d6 Nd5 Bxd2 Qxd2 Nxf3 gxf3 Qxb2 Nxc7 Kd7 Rd1 Qe5 Nxa8", 11, ["Nxf3", "Ne7"], "w", "7.Nd5 attacks queen, bishop and c7; after the trades Nxc7+ forks the king and wins the rook on a8."], ["oc-center-game-04", "center-game", "Center Game: Black Wins a Piece (...Nxf2)", "C22", "e4 e5 d4 exd4 Qxd4 Nc6 Qe3 Nf6 Bc4 Ne5 Bb3 Bb4 c3 Bc5 Qg3 Bxf2 Qxf2 Nd3 Kf1 Nxf2", 14, ["Qe2"], "b", "After 8.Qg3, 8...Bxf2+ deflects the queen and ...Nd3+ forks king and queen. 8.Qe2 covers d3."], ["oc-damiano-defense-01", "damiano-defense", "Damiano: 3...fxe5?? Qf7# King Hunt", "C40", "e4 e5 Nf3 f6 Nxe5 fxe5 Qh5 Ke7 Qxe5 Kf7 Bc4 Kg6 Qf5 Kh6 d4 g5 h4 Be7 hxg5 Kg7 Qf7", 5, ["Qe7"], "w", "Recapturing with the f-pawn opens the f-file and allows 4.Qh5+; White hunts the king down to mate on f7. 3...Qe7 is safer."], ["oc-damiano-defense-02", "damiano-defense", "Damiano: Punishing 3.Nxe5 (...Qe7)", "C40", "e4 e5 Nf3 f6 Nxe5 Qe7 Qh5 g6 Nxg6 Qxe4 Be2 Qxg6", 6, ["Nf3", "Nc4"], "b", "After 3...Qe7 White should retreat the knight; the premature 4.Qh5+ loses a piece to 4...g6."], ["oc-danish-gambit-01", "danish-gambit", "Danish Gambit: Qg4 Attack", "C21", "e4 e5 d4 exd4 c3 dxc3 Bc4 cxb2 Bxb2 Nf6 Nc3 Bb4 Ne2 Nxe4 O-O Nxc3 Nxc3 Bxc3 Bxc3 O-O Qg4", 19, ["Qg5"], "w", "Castling loses at once to 11.Qg4: queen and bishop both attack g7. 10...Qg5 avoids the attack."], ["oc-elephant-gambit-01", "elephant-gambit", "Elephant Gambit: 5...Bg4? 6.Bxf7+!", "C40", "e4 e5 Nf3 d5 exd5 Qxd5 Nc3 Qa5 Bc4 Bg4 Bxf7 Kxf7 Ng5 Ke8 Qxg4 Nf6 Qc8 Ke7 Qe6 Kd8 Nf7", 9, ["Nc6"], "w", "6.Bxf7+ Kxf7 7.Ng5+ opens the d1-g4 diagonal with check and wins the bishop; the line ends with 11.Nf7#."], ["oc-english-opening-01", "english-opening", "English: 3...Nxe4?? 4.Qa4+", "A10", "c4 d5 cxd5 Nf6 e4 Nxe4 Qa4", 5, ["c6"], "w", "4.Qa4+ attacks the king and the knight on e4 at once. The sound reply to 3.e4 is 3...c6."], ["oc-english-opening-02", "english-opening", "English: 7...d6? The Check Collects the Bishop", "A25", "c4 e5 Nc3 Nc6 g3 Bb4 Nd5 Nf6 Bg2 Nxd5 cxd5 Ne7 Nf3 d6 Qa4 Bd7 Qxb4 Nxd5 Qxb7", 13, ["O-O"], "w", "7...d6 opens the a4-e8 diagonal while the b4 bishop is undefended; 8.Qa4+ wins it. Castling first avoids the problem."], ["oc-fools-mate-01", "fools-mate", "Reversed Fool's Mate (Mate in 3 for White)", "B00", "e4 f6 d4 g5 Qh5", 3, ["e6", "e5", "Nc6"], "w", "2...g5?? opens the e8-h5 diagonal and allows 3.Qh5#; 2...e6 keeps ...g6 as a block."], ["oc-fools-mate-02", "fools-mate", "Fool's Mate (2-Move Checkmate)", "A00", "f3 e5 g4 Qh4", 2, ["e4"], "b", "2.g4?? opens the e1-h4 diagonal and allows 2...Qh4#, the fastest checkmate in chess."], ["oc-fools-mate-03", "fools-mate", "From's Gambit: Fool's Mate Pattern in Real Play", "A02", "f4 e5 fxe5 d6 exd6 Bxd6 Nc3 Qh4 g3 Bxg3 hxg3 Qxg3", 6, ["Nf3"], "b", "4.Nc3?? allows 4...Qh4+ and a queen mate on g3; 4.Nf3 covers h4."], ["oc-four-knights-game-01", "four-knights-game", "Three Knights: 6...Qh4+?? 7.g3", "C46", "e4 e5 Nf3 Nc6 Nc3 Bc5 Nxe5 Bxf2 Kxf2 Nxe5 d4 Qh4", 11, ["Ng6"], "w", "After 6...Qh4+ 7.g3 Qf6+ 8.Bf4 regains the knight; 6...Ng6 is safe."], ["oc-four-knights-game-02", "four-knights-game", "Four Knights: 7...h6? 8.Bxf6", "C49", "e4 e5 Nf3 Nc6 Nc3 Nf6 Bb5 Bb4 O-O O-O d3 d6 Bg5 h6", 13, ["Ne7", "Bxc3"], "w", "After 7...h6? 8.Bxf6 Qxf6 9.Nd5 forks the queen and the b4 bishop and wins a piece; 7...Ne7 avoids it."], ["oc-grunfeld-defense-01", "grunfeld-defense", "Grünfeld: 6.Nxd5?? Nxg5", "D91", "d4 Nf6 c4 g6 Nc3 d5 Nf3 Bg7 Bg5 Ne4 Nxd5", 10, ["cxd5", "Bf4", "Bh4"], "b", "After 6.Nxd5?? Nxg5 7.Nxg5 e6 Black wins a knight for two pawns."], ["oc-halloween-gambit-01", "halloween-gambit", "Halloween Gambit: Central Pawn Storm", "C47", "e4 e5 Nf3 Nc6 Nc3 Nf6 Nxe5 Nxe5 d4 Nc6 d5 Ne5 f4 Ng6 e5 Qe7 Qe2 Ng8", 17, ["d6"], "w", "9...Ng8?? loses to 10.d6! and the Nc7+ fork; 9...d6! counterattacks the centre."], ["oc-kings-gambit-01", "kings-gambit", "King's Gambit: Bxf7+/Be5# Attack", "C30", "e4 e5 f4 exf4 Bc4 Bc5 d4 Qh4 Kf1 Bb6 Nf3 Qd8 Bxf4 Ne7 Ng5 O-O", 15, ["d5"], "w", "After castling, White sacrifices on f7 and mates with Be5 on the long diagonal; ...d5! is safer."], ["oc-modern-benoni-01", "modern-benoni", "Modern Benoni: 7...Bg4? The Check That Wins the Queen", "A65", "d4 Nf6 c4 c5 d5 e6 Nc3 exd5 cxd5 d6 e4 g6 Nf3 Bg4 Qa4 Qd7 Bb5 Bxf3 Bxd7", 13, ["Bg7"], "w", "7...Bg4 pins, but 8.Qa4+ and 9.Bb5 win the queen; 7...Bg7 is correct."], ["oc-pirc-defense-01", "pirc-defense", "Pirc-Ufimtsev: Bxf7+/Ng5/Ne6", "B07", "e4 d6 Bc4 g6 Nf3 Bg7 d4 Nd7 Bxf7 Kxf7 Ng5 Ke8 Ne6", 7, ["Nf6"], "w", "4...Nd7 walls in the queen, and 5.Bxf7+ followed by 7.Ne6 wins material. 4...Nf6 avoids it."], ["oc-queens-gambit-declined-01", "queens-gambit-declined", "Elephant Trap", "D55", "d4 d5 c4 e6 Nc3 Nf6 Bg5 Nbd7 cxd5 exd5 Nxd5", 10, ["Nf3", "Bxf6"], "b", "6.Nxd5? Nxd5! and the ...Bb4+ zwischenzug leave Black a knight up for a pawn."], ["oc-slav-defense-01", "slav-defense", "Slav: 7.e3? Qa5+ and the g5-bishop is lost", "D10", "d4 d5 c4 c6 Nc3 Nf6 cxd5 cxd5 Bg5 Ne4 Nxe4 dxe4 e3 Qa5 Qd2 Qxg5", 12, ["a3"], "b", "After 6...dxe4, 7.e3? allows 7...Qa5+ and Black wins the bishop on g5; 7.a3 keeps equality."], ["oc-vienna-game-01", "vienna-game", "Vienna: ...Qxg2?? Bxf7+/Nxh3", "C25", "e4 e5 Nc3 d6 Bc4 Qg5 Nf3 Qxg2", 7, ["Qg6"], "w", "Grabbing g2 lets White sacrifice on f7, harass the queen and win it back."], ["oc-vienna-game-02", "vienna-game", "Vienna: Greedy Qxg7 Punished", "C25", "e4 e5 Nc3 Nc6 d3 Bc5 Qg4 Nf6 Qxg7 Bxf2 Kxf2 Rg8 Qh6 Ng4 Ke1 Nxh6", 8, ["Qg3"], "b", "Greedy Qxg7 fails to ...Bxf2+ and ...Rg8, which traps the queen."], ["oc-scholars-mate-01", "scholars-mate", "Wayward Queen: the ...g6?? Rook Grab", "C20", "e4 e5 Qh5 g6 Qxe5 Qe7 Qxh8", 3, ["Nc6"], "w", "...g6 kicks the queen, but Qxe5+ wins a pawn with check and forks the h8 rook; ...Nc6 first is correct."], ["oc-scholars-mate-02", "scholars-mate", "Scholar's Mate (4-Move Checkmate)", "C23", "e4 e5 Bc4 Nc6 Qh5 Nf6 Qxf7", 5, ["g6"], "w", "3...Nf6 ignores the threat on f7, allowing 4.Qxf7# mate; ...g6 first refutes it."], ["oc-scholars-mate-03", "scholars-mate", "Punishing the Wayward Queen (6.Qf3? Qxg5)", "C23", "e4 e5 Bc4 Bc5 Qh5 Qe7 Nf3 Nc6 Ng5 g6 Qf3 Qxg5 Qxf7 Kd8", 10, ["Qd1", "Qh3"], "b", "After ...g6 attacks the queen, 6.Qf3 leaves the g5 knight hanging to ...Qxg5."], ["oc-french-defense-01", "french-defense", "Advance French: the ...Nxd4 Queen Trap", "C02", "e4 e6 d4 d5 e5 c5 c3 Nc6 Nf3 Qb6 Bd3 cxd4 cxd4 Nxd4", 13, ["Bd7"], "w", "Capturing on d4 too early loses the queen to a Bb5+ fork; ...Bd7 first makes the capture safe."], ["oc-french-defense-02", "french-defense", "French Classical: Qe4 Double Attack", "C00", "e4 e6 d4 d5 Nc3 Nf6 Bg5 dxe4 Nxe4 Nbd7 Bd3 Be7 Nxf6 Nxf6 Nf3 O-O Qe2 b6 Bxf6 Bxf6 Qe4", 17, ["c5"], "w", "Premature ...b6 opens the long diagonal, and Qe4 double-attacks h7 and the a8 rook."], ["oc-french-defense-03", "french-defense", "French Steiner: Qe6# Attack", "C00", "e4 e6 c4 d5 cxd5 exd5 Qa4 Bd7 Qb3 dxe4 Bc4 Qe7 Qxb7 Bc6 Qc8 Qd8 Bxf7 Ke7 Qe6", 13, ["Nf6"], "w", "Black's passive defence lets the queen raid b7, and ...Bc6 walks into Qc8+ and mate on e6."], ["oc-french-defense-04", "french-defense", "Advance French: 7-move Qe3# trap", "C02", "e4 e6 d4 d5 e5 c5 dxc5 Bxc5 f4 Qb6 Ne2 Bf2 Kd2 Qe3", 10, ["Nf3"], "b", "After 5.f4, f2 is weak; 6.Ne2 fails to guard it and the bishop sacrifice on f2 leads to mate on e3."], ["oc-french-defense-05", "french-defense", "French Two Knights: 11.Nc3? Qxb2", "C00", "e4 e6 Nf3 d5 Nc3 Nf6 e5 Nfd7 d4 c5 Bg5 Qb6 dxc5 Bxc5 Qd2 Nc6 Na4 Bxf2 Qxf2 Qb4 Nc3 Qxb2 Kd2 Qxa1", 20, ["c3", "Bd2"], "b", "Saving the knight with Nc3 leaves b2 hanging and the queen then wins the a1 rook; 11.c3 is sounder."], ["oc-scandinavian-defense-01", "scandinavian-defense", "Scandinavian: ...Qxd4?? Bxc6+", "B01", "e4 d5 exd5 Qxd5 d4 Nc6 Nf3 Bg4 Be2 Bxf3 Bxf3 Qxd4", 11, ["Qd7", "Qd6"], "w", "Grabbing d4 with the queen allows Bxc6+, winning the queen for a bishop."], ["oc-scandinavian-defense-02", "scandinavian-defense", "Scandinavian: Greedy ...Qxh1 Trapped", "B01", "e4 d5 exd5 Qxd5 Nc3 Qa5 d4 Nf6 Nf3 Bg4 h3 Qh5 hxg4 Qxh1 Ne2 Nxg4 Ng3", 11, ["Bh5"], "w", "Qh5 invites hxg4, and the queen that grabs the h1 rook gets trapped by Ne2 and Ng3."], ["oc-scandinavian-defense-03", "scandinavian-defense", "Scandinavian: Légal-style Bxf7#", "B01", "e4 d5 exd5 Qxd5 Nc3 Qd8 Nf3 Bg4 Bc4 Nf6 Ne5 Bxd1 Bxf7", 11, ["Be6"], "w", "After Ne5, capturing the queen with Bxd1 allows Bxf7# mate. Be6 keeps material level."], ["oc-scandinavian-defense-04", "scandinavian-defense", "Scandinavian: ...Bh5?? Bxf7#", "B01", "e4 d5 exd5 Qxd5 Nc3 Qd8 Nf3 Bg4 Bc4 Nf6 Ne5 Bh5 Qxh5 Nxh5 Bxf7", 11, ["Be6"], "w", "Retreating to h5 leaves the bishop loose after Qxh5, and Bxf7# follows."], ["oc-scandinavian-defense-05", "scandinavian-defense", "Scandinavian: Nd6# Smother", "B01", "e4 d5 exd5 Qxd5 Nc3 Qa5 d4 Nf6 Bc4 Bf5 Bd2 c6 Qe2 Nbd7 Nb5 Qd8 Nd6", 13, ["Qc7"], "w", "Nbd7 blocks the king and allows a smothered mate with Nb5 and Nd6#; ...Qc7 guards d6."], ["oc-scotch-game-01", "scotch-game", "Scotch: ...Qxe4?? Ndb5/Nxc7", "C45", "e4 e5 Nf3 Nc6 d4 exd4 Nxd4 Qh4 Nc3 Bb4 Be2 Qxe4 Nb5 Ba5 Nxc7 Bxc7 Nxe4", 13, ["Bxc3"], "w", "Grabbing e4 looks safe under the pin, but Nb5 and Nxc7+ deflect the bishop and Nxe4 wins the queen."], ["oc-scotch-game-02", "scotch-game", "Scotch: Qf6/Nb5 Material Win", "C45", "e4 e5 Nf3 Nc6 d4 exd4 Nxd4 Bc5 Be3 Qf6 Nb5 Bxe3 fxe3 Qh4 g3 Qxe4 Nxc7 Kd8 Nxa8 Qxh1 Qd6 Nge7 Nd2 Qd5 Qc7 Ke8 Qxc8 Nxc8 Nc7", 23, ["Nf5"], "w", "Centralising the queen on d5 walks into Qc7+ and Qxc8+, then Nc7+ forks king and queen."], ["oc-scotch-game-03", "scotch-game", "Scotch: 6...Nf6? Walks Past the Battery", "C45", "e4 e5 Nf3 Nc6 d4 exd4 Nxd4 Bb4 c3 Bc5 Be3 Nf6 Nxc6 bxc6 Bxc5", 11, ["Qf6", "d6"], "w", "Nf6 ignores the Be3 battery aimed at c5; after the knight trade Bxc5 wins the bishop."], ["oc-scotch-game-04", "scotch-game", "Scotch: 7...Bb4+? The Second Check Costs the Bishop", "C45", "e4 e5 Nf3 Nc6 d4 exd4 Nxd4 Bb4 c3 Bc5 Be3 Nxd4 cxd4 Bb4 Nc3 d5 Qa4 c6 Qxb4", 13, ["Bb6"], "w", "Repeating the check after the d4 trade allows Nc3, and Qa4+ then Qxb4 collects the bishop."], ["oc-italian-game-01", "italian-game", "Italian: 9...Nxc3 Overreach", "C50", "e4 e5 Nf3 Nc6 Bc4 Bc5 c3 Nf6 d4 exd4 cxd4 Bb4 Nc3 Nxe4 O-O Bxc3 bxc3 Nxc3 Qe1 Qe7 Qxc3", 17, ["d5"], "w", "Taking on c3 again lets White play Qe1+ and win the knight; 9...d5 is sound."], ["oc-italian-game-02", "italian-game", "Evans Gambit: 11...Qe7? 12.Qxc3", "C51", "e4 e5 Nf3 Nc6 Bc4 Bc5 b4 Bxb4 c3 Bc5 d4 exd4 O-O dxc3 Bxf7 Kxf7 Qd5 Ke8 Qh5 g6 Qxc5 Qe7 Qxc3 d6 Qxh8", 21, ["Qf6"], "w", "Offering a queen trade allows Qxc3 and Qxh8 along the long diagonal; 11...Qf6 avoids it."], ["oc-italian-game-03", "italian-game", "Fried Liver: 8...Nd4? Too Slow", "C57", "e4 e5 Nf3 Nc6 Bc4 Nf6 Ng5 d5 exd5 Nxd5 Nxf7 Kxf7 Qf3 Ke6 Nc3 Nd4 Bxd5 Ke7 Qf7 Kd6 Ne4", 15, ["Nb4", "Ne7"], "w", "8...Nd4 leaves the d5 knight unguarded to Bxd5+ and mate on move eleven."], ["oc-italian-game-04", "italian-game", "Italian: 8...f6? The Bishop Is Not Really Trapped", "C55", "e4 e5 Nf3 Nc6 Bc4 Nf6 d3 d5 exd5 Nxd5 O-O Bg4 h3 Bh5 Re1 f6 Nxe5 Bxd1 Nxc6 Kd7 Nxd8 Bxc2 Ne6 c6 Nxf8", 15, ["Qd6"], "w", "Defending e5 with ...f6 hangs it to Nxe5, and a discovered check wins material."], ["oc-italian-game-05", "italian-game", "Blackburne Shilling Gambit", "C50", "e4 e5 Nf3 Nc6 Bc4 Nd4 Nxe5 Qg5 Nxf7 Qxg2 Rf1 Qxe4 Be2 Nf3", 6, ["Nxd4", "O-O"], "b", "4.Nxe5 falls to 4...Qg5 and a smothered mate; 4.Nxd4 or castling is safe."], ["oc-italian-game-06", "italian-game", "Italian: 6.Re1?? Bxf2+", "C50", "e4 e5 Nf3 Nc6 Bc4 Bc5 O-O Nf6 c3 Nxe4 Re1 Bxf2 Kh1 Bxe1", 10, ["d4"], "b", "Re1 drops f2 to ...Bxf2+ forking king and rook; 6.d4 is the safe move."], ["oc-queens-gambit-accepted-01", "queens-gambit-accepted", "QGA Salvio Trap (Qxc6+)", "D20", "d4 d5 c4 dxc4 e3 b5 a4 c6 axb5 cxb5 Qf3 Nc6 Qxc6", 11, ["Bb7", "Nf6", "e6"], "w", "After 6.Qf3 the a8 rook is attacked on the open diagonal and Black loses material."], ["oc-queens-gambit-accepted-02", "queens-gambit-accepted", "QGA Salvio Trap (Qxa8)", "D20", "d4 d5 c4 dxc4 e3 b5 a4 c6 axb5 cxb5 Qf3 Nf6 Qxa8", 11, ["Bb7"], "w", "6...Nf6 misses 7.Qxa8, taking the rook on the long diagonal."], ["oc-queens-gambit-accepted-03", "queens-gambit-accepted", "QGA: 6.Qa4+ Bxf7+/Ng5+", "D20", "d4 d5 c4 dxc4 Nf3 Nf6 e3 g6 Bxc4 Bg7 Qa4 Nbd7 Bxf7 Kxf7 Ng5 Ke8 Ne6", 11, ["c6", "Qd7"], "w", "Blocking with Nbd7 corks the d-file and allows Bxf7+, Ng5+ and Ne6; block with ...c6 instead."], ["oc-queens-gambit-accepted-04", "queens-gambit-accepted", "QGA: 7...Nxd4? The Bishop Steps Aside", "D20", "d4 d5 c4 dxc4 e4 e6 Bxc4 Nc6 Nf3 Bb4 Nc3 Nf6 Bd3 Nxd4 Nxd4 Qxd4 Bb5 c6 Qxd4", 13, ["O-O"], "w", "Grabbing d4 fails because Bb5+ wins the queen; castling is safe."], ["oc-queens-gambit-accepted-05", "queens-gambit-accepted", "QGA McDonnell: 7...Bxf3?? 8.Bxf7+", "D20", "d4 d5 c4 dxc4 e4 e5 Nf3 exd4 Bxc4 Nc6 O-O Bg4 Qb3 Bxf3 Bxf7 Ke7 Qe6", 13, ["Qd7"], "w", "Taking the knight allows Bxf7+ and Qe6 mate, with the queen guarded by the bishop."], ["oc-queens-gambit-accepted-06", "queens-gambit-accepted", "QGA: 5...exd4? An Eight-Move King Hunt", "D20", "d4 d5 c4 dxc4 e4 e5 Nf3 Bg4 Bxc4 exd4 Bxf7 Kxf7 Ne5 Ke6 Qxg4 Kxe5 Bf4 Kxe4 Nc3 Kd3 Qe2", 9, ["Bxf3"], "w", "Taking d4 allows a forced sacrifice on f7 and a king hunt ending in mate."], ["oc-queens-gambit-accepted-07", "queens-gambit-accepted", "QGA Greco: 8...e6? Fourteen Moves to Mate", "D20", "d4 d5 c4 dxc4 e4 b5 a4 c6 axb5 cxb5 Nc3 a6 Nxb5 Bb7 Nc3 e6 Bxc4 Bb4 Qa4 Bc6 Qxb4 Qxd4 Nf3 Qf6 O-O Ne7 Bg5 Qg6 Qxe7", 15, ["Nf6"], "w", "Closing with ...e6 leaves the king's light squares undeveloped; Bxc4 and a chain of checks lead to mate."], ["oc-englund-gambit-01", "englund-gambit", "Englund Nd5! (Nxc7# Boxed-King Mate)", "A40", "d4 e5 dxe5 Nc6 Nf3 Qe7 Nc3 Nxe5 e4 Nf6 Bg5 h6 Nd5 Nxf3 Qxf3 Qxe4", 15, ["Qe5"], "w", "After 8...Qxe4+ 9.Qxe4+ Nxe4 10.Nxc7# mates; 8...Qe5 avoids the trade."], ["oc-englund-gambit-02", "englund-gambit", "Englund Long Mate (Rd8# in 16)", "A40", "d4 e5 dxe5 Nc6 Nf3 Qe7 Bf4 Qb4 Bd2 Qxb2 Nc3 Bb4 Rb1 Qa3 Nd5 Bxd2 Qxd2 Qxa2 Rd1 Kd8 Ng5 Nxe5 Qc3 f6 Ne6 dxe6 Qxc7 Ke8 Nxf6 gxf6 Rd8", 21, ["Nh6"], "w", "11...Nxe5 wins a pawn but opens the c-file to 12.Qc3 and a long attack ending in Rd8 mate."], ["oc-englund-gambit-03", "englund-gambit", "Englund: 6...Nf6? 7.Bg5 and the c7 Mate", "A40", "d4 e5 dxe5 Nc6 Nf3 Qe7 Nc3 Nxe5 e4 Nxf3 Qxf3 Nf6 Bg5 h6 Nd5 Qxe4 Qxe4 Nxe4 Nxc7", 11, ["Qf6"], "w", "After 7.Bg5 h6 8.Nd5 the queen trade on e4 runs into Nxc7 mate."], ["oc-englund-gambit-04", "englund-gambit", "Englund Gambit Trap", "A40", "d4 e5 dxe5 Nc6 Nf3 Qe7 Bf4 Qb4 Bd2 Qxb2 Bc3 Bb4 Qd2 Bxc3 Qxc3 Qc1", 10, ["Nc3"], "b", "6.Bc3 allows ...Bb4 pinning the bishop; after 7.Qd2 Bxc3 8.Qxc3 Qc1 is mate."], ["oc-englund-gambit-05", "englund-gambit", "Rosen Trap (Bxf2+ Qxd1)", "A40", "d4 e5 dxe5 Bc5 Nf3 d6 exd6 Ne7 dxe7 Bxf2 Kxf2 Qxd1", 8, ["e3", "Nc3", "Bf4", "b3"], "b", "5.dxe7 opens the d-file; 5...Bxf2+ forces Kxf2 and Qxd1 wins the queen."], ["oc-englund-gambit-06", "englund-gambit", "Englund Nb4 Fork Trap", "A40", "d4 e5 dxe5 Nc6 Nf3 Qe7 Bf4 Qb4 Bd2 Qxb2 Nc3 Nb4 a3 Nxc2 Qxc2 Qxc2", 12, ["Nd4", "Rb1"], "b", "7.a3 allows ...Nxc2+ and after Qxc2 Qxc2 Black wins the queen."], ["oc-englund-gambit-07", "englund-gambit", "Englund c3 Trap (Nd3#)", "A40", "d4 e5 dxe5 Nc6 Nf3 Qe7 c3 Nxe5 Bd2 Nd3", 8, ["Nxe5", "Bf4"], "b", "After 5.Bd2?? the knight jumps to d3 with mate, since the e2 pawn is pinned."], ["oc-englund-gambit-08", "englund-gambit", "Englund: 5.Qd2?? and the queen reaches c1", "A40", "d4 e5 dxe5 Nc6 Nf3 Qe7 Bf4 Qb4 Qd2 Qxb2 Qc3 Bb4 Bd2 Bxc3 Bxc3 Qc1", 8, ["Bd2"], "b", "5.Qd2 allows ...Qxb2 and a pin with ...Bb4, ending in ...Qc1 mate."], ["oc-englund-gambit-09", "englund-gambit", "Englund: 6.Rb1?? Qxc3+", "A40", "d4 e5 dxe5 Nc6 Nf3 Qe7 Bg5 Qb4 Nc3 Qxb2 Rb1 Qxc3", 10, ["Bd2", "Nd5"], "b", "6.Rb1 saves the rook but ignores ...Qxc3+, winning a piece."], ["oc-englund-gambit-10", "englund-gambit", "Englund: 7.g3? Qxe4+ and the h1-rook falls", "A40", "d4 e5 d5 Bc5 c4 d6 e4 f5 f3 fxe4 fxe4 Qh4 g3 Qxe4 Qe2 Qxh1", 12, ["Kd2"], "b", "7.g3 blocks the check, but 7...Qxe4+ hits the king and the h1 rook together."], ["oc-englund-gambit-11", "englund-gambit", "Englund: 8.Kxf2?? Nxe4+", "A40", "d4 e5 d5 Bc5 e4 d6 Nf3 f5 Bd3 fxe4 Bxe4 Nf6 Bg5 Bxf2 Kxf2 Nxe4 Kg1 Nxg5 Nxg5 Qxg5 h3 O-O Nc3 e4 Nxe4 Qe3 Kh2 Qxe4", 14, ["Ke2", "Kf1"], "b", "8.Kxf2 allows ...Nxe4+, forking king and bishop; 8.Ke2 keeps the king off f2."], ["oc-philidor-defense-01", "philidor-defense", "Légal Trap (Légal's Mate)", "C41", "e4 e5 Nf3 d6 Bc4 Bg4 Nc3 g6 Nxe5 Bxd1 Bxf7 Ke7 Nd5", 9, ["dxe5"], "w", "5...Bxd1 wins the queen, but 6.Bxf7+ Ke7 7.Nd5 is mate; 5...dxe5 keeps material."], ["oc-philidor-defense-02", "philidor-defense", "Philidor: 9...h6? Asking the Bishop While the Knight Waits", "C41", "e4 e5 Nf3 d6 d4 Bg4 dxe5 Bxf3 Qxf3 dxe5 Qb3 b6 Nc3 Nf6 Bc4 Qe7 Bg5 h6 Nd5 Qd6 Nxf6 gxf6 Bxf7 Ke7 Rd1 Qc5 Qe6", 17, ["c6"], "w", "After 9...h6? 10.Nd5 hits the pinned knight twice and Qe6 mates; 9...c6 takes d5 away."], ["oc-philidor-defense-03", "philidor-defense", "Philidor: 9...cxd5? Opens the Line to the King", "C41", "e4 e5 Nf3 d6 d4 Bg4 dxe5 Bxf3 Qxf3 dxe5 Bc4 Qf6 Qb3 b6 Nc3 c6 Nd5 cxd5 Bb5 Nd7 Bxd7 Kxd7 Qxd5 Qd6 Qxa8 Nf6 Qxa7 Qc7 Qxc7", 17, ["Qd8"], "w", "Taking the knight allows 10.Bb5+ and a queen raid on d5 and a8; retreating the queen holds."], ["oc-philidor-defense-04", "philidor-defense", "Philidor: ...b6 saves b7, Bxf7+ and Qe6 mates", "C41", "e4 e5 Nf3 d6 Bc4 Bg4 h3 Bxf3 Qxf3 Nf6 Qb3 b6 Bxf7 Ke7 Qe6", 11, ["d5"], "w", "6...b6 leaves f7 open: 7.Bxf7+ Ke7 8.Qe6 is mate; 6...d5 closes the bishop's diagonal."], ["oc-philidor-defense-05", "philidor-defense", "Philidor: the queen guards f7, Qxb7 wins the rook", "C41", "e4 e5 Nf3 d6 Bc4 Bg4 h3 Bxf3 Qxf3 Nf6 Qb3 Qe7 Qxb7 Nxe4 Qxa8 Qf6 Qxb8 Ke7 Qxc7 Ke8 Bb5", 11, ["d5"], "w", "6...Qe7 guards f7, but 7.Qxb7 wins the a8 rook; 6...d5 holds."], ["oc-philidor-defense-06", "philidor-defense", "Philidor: 6...Bg4?? 7.Bxf7+ and 8.Ne5+", "C41", "e4 e5 Nf3 d6 Bc4 h6 d4 exd4 Nxd4 c5 Nf3 Bg4 Bxf7 Kxf7 Ne5 dxe5 Qxd8", 11, ["Be6"], "w", "6...Bg4? 7.Bxf7+ Kxf7 8.Ne5+ removes the pin with check and wins the queen; 6...Be6 is safe."], ["oc-philidor-defense-07", "philidor-defense", "Philidor: 7...Ne4? 8.Qd5 hits the knight and f7", "C41", "e4 e5 Nf3 d6 Bc4 h6 d4 exd4 Nxd4 c5 Nf3 Nf6 e5 Ne4 Qd5 Be6 Qxe4 d5 Bb5 Nd7 Qd3 a6 Bxd7", 13, ["d5"], "w", "7...Ne4? is met by 8.Qd5 attacking the knight and f7; 7...d5 hits the bishop first."], ["oc-philidor-defense-08", "philidor-defense", "Philidor: 5...Qf6? 6.Qb3 and the knight comes to d5", "C41", "e4 e5 Nf3 d6 Bc4 Bg4 h3 Bxf3 Qxf3 Qf6 Qb3 b6 Nc3 c6 Nd5 cxd5 Bxd5 Nd7 Bxa8", 9, ["Qd7"], "w", "5...Qf6? allows 6.Qb3 and Nd5 with Bxd5 hitting a8; 5...Qd7 guards f7."], ["oc-philidor-defense-09", "philidor-defense", "Philidor: 9...Be6? 10.Bxe6 and Nf7+ wins the rook", "C41", "e4 e5 Nf3 d6 Bc4 h6 d4 exd4 Nxd4 c5 Nf3 Nf6 e5 dxe5 Qxd8 Kxd8 Nxe5 Be6 Bxe6 fxe6 Nf7 Ke7 Nxh8 Nc6 Ng6 Kf7 Nxf8", 17, ["Rh7"], "w", "9...Be6? 10.Bxe6 fxe6 lets 11.Nf7+ fork king and rook; 9...Rh7 removes the rook from the fork."], ["oc-russian-game-01", "russian-game", "Petroff: 3.Bc4 Greed (Qxb7/Qxa8)", "C42", "e4 e5 Nf3 Nf6 Bc4 Nxe4 Nc3 Nxc3 dxc3 d6 Ng5 Be6 Bxe6 fxe6 Qf3 Qf6 Qxb7 h6 Qxa8 hxg5 Qxb8", 9, ["f6"], "w", "5...d6 ignores 6.Ng5; White's queen then wins b7, a8 and b8."], ["oc-russian-game-02", "russian-game", "Petroff: Cochrane Gambit Bxd8", "C42", "e4 e5 Nf3 Nf6 Nxe5 d6 Nxf7 Kxf7 d4 Nxe4 Qh5 Ke7 Qe2 d5 Bg5 Ke8 Bxd8", 9, ["c5"], "w", "After 5.d4, grabbing on e4 walks into Qh5+ and Qe2, and Bxd8 wins the queen."], ["oc-russian-game-03", "russian-game", "Petroff: 5...Be7? 6.Qa4+", "C42", "e4 e5 Nf3 Nf6 Nxe5 d6 Nf3 Nxe4 c3 Be7 Qa4 Bd7 Qxe4", 9, ["d5", "Nc6"], "w", "After 5.c3, ...Be7 allows Qa4+ forking king and the e4 knight."], ["oc-russian-game-04", "russian-game", "Petroff: Légal-style Bg5#", "C42", "e4 e5 Nf3 Nf6 Nxe5 d6 Nf3 Nxe4 Nc3 Nxc3 dxc3 Bg4 Be3 Nc6 Bc4 Ne5 Nxe5 Bxd1 Bxf7 Ke7 Bg5", 17, ["Be7"], "w", "After 9...Bxd1 10.Bxf7+ Ke7 11.Bg5 is mate."], ["oc-russian-game-05", "russian-game", "Petroff: 4...d5? The Knight Has Nowhere Safe", "C42", "e4 e5 Nf3 Nf6 Nxe5 Nxe4 Qe2 d5 d3 Nf6 Nc6 Qe7 Nxe7", 9, ["Qe7"], "w", "With the e-file open, 6.Nc6+ is a discovered check forking the queen."], ["oc-russian-game-06", "russian-game", "Petroff: 5...Nxe4? 6.Qg4", "C42", "e4 e5 Nf3 Nf6 Nc3 Bb4 Nxe5 Bxc3 dxc3 Nxe4 Qg4 Nf6 Qxg7 Rg8 Qxf7", 9, ["d6", "Qe7"], "w", "5...Nxe4 allows 6.Qg4 hitting e4 and g7; after 7.Qxg7 and 8.Qxf7 White mates."], ["oc-russian-game-07", "russian-game", "Petroff: Black Wins a Piece (...f4)", "C42", "e4 e5 Nf3 Nf6 Nxe5 Nxe4 Qe2 Qe7 Qxe4 d6 d4 dxe5 dxe5 Nc6 Bf4 g5 Bg3 f5 Qe2 f4", 14, ["Nc3"], "b", "8.Bf4 lets ...g5 and ...f5 trap the bishop; ...f4 wins it for two pawns."], ["oc-russian-game-08", "russian-game", "Petroff: ...Qg5 hits e5 and g2", "C42", "e4 e5 Nf3 Nf6 Bc4 Nxe4 Nxe5 d5 Bd3 Qg5 Nf3 Qxg2 Rg1 Qxf2", 8, ["Be2"], "b", "5.Bd3 allows ...Qg5 hitting e5 and g2; ...Qxg2 and ...Qxf2 is mate."], ["oc-russian-game-09", "russian-game", "Petroff: 5.Nxf7? Qe7!", "C42", "e4 e5 Nf3 Nf6 Bc4 Nxe4 Nxe5 d5 Nxf7 Qe7 Bxd5 Ng3 Qe2 Qxe2", 8, ["Be2"], "b", "5.Nxf7 Qe7 lines up the e-file; knight checks win White's queen and ...Qxe2 is mate."], ["oc-russian-game-10", "russian-game", "Petroff: 6.Bb5? in the fork trick", "C42", "e4 e5 Nf3 Nf6 Nc3 Nc6 Bc4 Nxe4 Nxe4 d5 Bb5 dxe4 Bxc6 bxc6 Nxe5 Qg5 Ng4 Qxg4 Qxg4 Bxg4", 10, ["Bd3"], "b", "6.Bb5 dxe4 and 8...Qg5 double-attacks e5 and g2, leaving Black a piece up."], ["oc-russian-game-11", "russian-game", "Petroff: Bd3? Qg5! and the pin on the e-file", "C42", "e4 e5 Nf3 Nf6 Bc4 Nxe4 Nxe5 d5 Qf3 Be6 Bd3 Qg5 Bxe4 Qxe5 O-O dxe4", 10, ["d4"], "b", "6.Bd3 allows ...Qg5 hitting the loose e5 knight; the bishop on e4 gets pinned and ...dxe4 wins a piece."], ["oc-russian-game-12", "russian-game", "Petroff: 8.Qe3?? and the knight fork on c2", "C42", "e4 e5 Nf3 Nf6 Bc4 Nxe4 Qe2 d5 Bb3 Nc6 d3 Nc5 Nxe5 Nd4 Qe3 Ncxb3 axb3 Nxc2 Kd2 Nxe3 fxe3 Qg5 Nxf7 Qxg2 Kc3 Qxh1", 14, ["Qd1"], "b", "8.Qe3 walks into ...Ncxb3 and a knight fork on c2 that wins material."], ["oc-russian-game-13", "russian-game", "Petroff: 8.Bxf6? opens the e-file for Re8", "C42", "e4 e5 Nf3 Nf6 Nxe5 d6 Nf3 Nxe4 d3 Nf6 Bg5 Be7 Qe2 O-O Bxf6 Bxf6 Nc3 Bxc3 bxc3 Re8 Qxe8 Qxe8", 14, ["Nc3"], "b", "8.Bxf6 Bxf6 clears the way for ...Re8, pinning the queen; Nc3 keeps the e-file closed."], ["oc-russian-game-14", "russian-game", "Petroff: 8.O-O? h6 and the g5-knight is stranded", "C42", "e4 e5 Nf3 Nf6 Nc3 Nc6 Bc4 Nxe4 Bxf7 Kxf7 Nxe4 d5 Neg5 Kg8 O-O h6 Nh3 Bg4 d3 Nd4 c3 Nxf3 gxf3 Bxh3", 14, ["d4"], "b", "After 8.O-O h6 the g5 knight has only h3, where ...Bg4 and ...Nd4 win it."], ["oc-russian-game-15", "russian-game", "Petroff: 13.Rxe4?? Bxh2+", "C42", "e4 e5 Nf3 Nf6 Nc3 Nc6 Bc4 Nxe4 Nxe4 d5 Bd3 dxe4 Bxe4 Bd6 O-O O-O d3 f5 Bxc6 bxc6 Re1 e4 dxe4 fxe4 Rxe4 Bxh2 Kxh2 Qxd1 b3 Qxc2", 24, ["Bg5"], "b", "13.Rxe4 Bxh2+ then ...Qxd1 wins the queen on the open d-file; Bg5 is safer."], ["oc-london-system-01", "london-system", "Jobava London Nb5 Trap", "D00", "d4 d5 Bf4 Nf6 Nc3 Nc6 Nb5 e6 Nxc7 Kd7 Nxa8", 5, ["e6", "a6"], "w", "After 3...Nc6, 4.Nb5 targets c7 and Nxc7+ forks king and rook."], ["oc-london-system-02", "london-system", "London Nb5 Fork: The ...e5 Counter Fails", "D00", "d4 d5 Bf4 Nf6 e3 c5 Nc3 Nc6 Nb5 e5 dxe5 Ne4 Qxd5 Qxd5 Nc7 Kd8 Nxd5", 7, ["e6"], "w", "After 4...Nc6 5.Nb5, the ...e5 counter opens lines and Nc7+ forks, winning two pawns."], ["oc-london-system-03", "london-system", "London b2 Poisoned Pawn: Queen Trapped on a2", "D02", "d4 d5 Bf4 e6 Nf3 c5 e3 Qb6 Nc3 Qxb2 Nb5 Na6 a3 Nf6 Rb1 Qa2 Qc1 c4 Rb2", 9, [], "w", "Grabbing b2 lets White trap the queen on a2 with Nb5, a3, Rb1 and Qc1."], ["oc-london-system-04", "london-system", "London b2 Grab: Nc7+ Wins the Rook", "D02", "d4 d5 Bf4 e6 Nf3 c5 e3 Qb6 Nc3 Qxb2 Nb5 Qb4 c3 Qa5 Nc7 Kd8 Nxa8", 13, [], "w", "After grabbing b2, ...Qa5 allows Nc7+ forking king and rook."], ["oc-london-system-05", "london-system", "London Greek Gift: Ne4 Hits the Queen", "D00", "d4 d5 Bf4 Nf6 e3 c5 c3 e6 Nf3 Nc6 Nbd2 Bd6 Bg3 O-O Bd3 Qe7 Ne5 Nd7 Nxd7 Bxd7 Bxd6 Qxd6 dxc5 Qxc5 Bxh7 Kxh7 Qh5 Kg8 Ne4 g6 Nxc5 gxh5 Nxd7 Rfd8 Nf6 Kg7 Nxh5", 23, [], "w", "Recapturing on c5 lets the Greek Gift sacrifice work: Ne4 hits the queen."], ["oc-london-system-06", "london-system", "London 4.dxc5: The c7 Discovered Check", "D00", "d4 d5 Bf4 Nf6 e3 c5 dxc5 e6 b4 a5 c3 b6 Bxb8 Rxb8 Bb5 Bd7 c6 Bc8 c7", 11, [], "w", "Chasing the c5 pawn with ...b6 allows Bxb8 and a c-pawn run ending in a discovered check."], ["oc-london-system-07", "london-system", "London e4 Break: Rd7 Invasion", "D00", "d4 d5 Bf4 Nf6 e3 e6 Nf3 c5 c3 Nc6 Nbd2 Bd6 Bg3 O-O Bd3 b6 e4 dxe4 Nxe4 Nxe4 Bxe4 Bb7 dxc5 Bxc5 Qa4 Na5 Rd1 Qe7 Rd7", 27, ["Nc6"], "w", "With d7 unguarded, Rd7 invades and hits queen and bishop."], ["oc-london-system-08", "london-system", "London Greek Gift: King Hunt to Qf4#", "D00", "d4 d5 Bf4 Nf6 e3 e6 Nf3 c5 c3 Nc6 Nbd2 Bd6 Bg3 O-O Bd3 b6 e4 dxe4 Nxe4 Nxe4 Bxe4 Bb7 dxc5 Bxc5 Qa4 Na5 Rd1 Qe8 Bxh7 Kxh7 Qh4 Kg6 Ne5 Kf5 Qf4", 31, ["Kg8"], "w", "After the Greek Gift, ...Kg6 walks into Ne5+ and Qf4 mate."], ["oc-london-system-09", "london-system", "London Greek Gift (Bxh7+ and Ng5)", "D00", "d4 d5 Bf4 Nf6 e3 c5 c3 e6 Nf3 Nc6 Nbd2 Bd6 Bg3 O-O Bd3 Qe7 Ne5 Nd7 Nxd7 Qxd7 Bxd6 Qxd6 dxc5 Qxc5 Bxh7 Kxh7 Qh5 Kg8 Ne4 Qe7 Ng5 Qxg5 Qxg5", 29, ["g6"], "w", "After ...Qe7, Ng5 threatens Qh7+ and Qh8 mate, forcing Black to give up the queen."], ["oc-london-system-10", "london-system", "London Greek Gift Mate (Qh8#)", "D00", "d4 d5 Bf4 Nf6 e3 c5 c3 e6 Nf3 Nc6 Nbd2 Bd6 Bg3 O-O Bd3 Qe7 Ne5 Nd7 Nxd7 Qxd7 Bxd6 Qxd6 dxc5 Qxc5 Bxh7 Kxh7 Qh5 Kg8 Ne4 Qe7 Ng5 Re8 Qh7 Kf8 Qh8", 31, ["Qxg5"], "w", "After 16...Re8 the king gets f8, but Qh7+ and Qh8 are mate."], ["oc-london-system-11", "london-system", "London: 11...Nd7? The Greek Gift Cashes In", "D02", "d4 d5 Nf3 Nf6 Bf4 e6 e3 c5 c3 cxd4 exd4 Bd6 Bg3 O-O Nbd2 Nc6 Bd3 Re8 Ne5 Qc7 f4 Nd7 Bxh7 Kxh7 Qh5 Kg8 Qxf7 Kh8 Qxe8", 21, ["Ne7"], "w", "Nd7 lets Bxh7+ and Qxf7+, and Qxe8+ then wins the rook."], ["oc-london-system-12", "london-system", "London 3.c3 Qb6: The Open a-File", "A45", "d4 Nf6 Bf4 c5 c3 Qb6 Qb3 cxd4 Qxb6 axb6 cxd4 Nc6 e3 Nb4 Kd1 Nxa2", 6, ["Qc2"], "b", "After the queen trade, ...axb6 opens the a-file and a2 falls."], ["oc-london-system-13", "london-system", "Anti-London 2...h5!?: Hunting the Bishop", "D00", "d4 d5 Bf4 h5 e3 e5 dxe5 g5 Bg3 h4", 6, ["Bxe5"], "b", "After 4.dxe5, ...g5 and ...h4 trap the London bishop on g3."], ["oc-london-system-14", "london-system", "London: 5.Bxe5?? and the Qa5+ Trick", "A45", "d4 Nf6 Bf4 c5 Nf3 cxd4 Nxd4 e5 Bxe5 Qa5 Nc3 Qxe5", 8, ["Nb3"], "b", "After 5.Bxe5, ...Qa5+ checks and then hits the undefended bishop."], ["oc-london-system-15", "london-system", "London with b3: The ...Ba3 Invasion", "A45", "d4 Nf6 Bf4 c5 c3 Qb6 b3 d5 Nf3 Bf5 e3 Nc6 Nbd2 e6 Be2 cxd4 exd4 Ba3", 6, [], "b", "After 4.b3, ...Ba3 invades a square no pawn can challenge."], ["oc-london-system-16", "london-system", "London: 10.Nxe5? and ...Nh5 Wins the Bishop", "A45", "d4 Nf6 Bf4 c5 e3 cxd4 exd4 g6 c3 Bg7 Nf3 O-O Nbd2 d6 Bd3 e5 dxe5 dxe5 Nxe5 Nh5 Bg3 Nxg3 hxg3 Bxe5", 18, [], "b", "After 10.Nxe5, ...Nh5 attacks the f4 bishop, the knight's only defender, and Black wins a piece."], ["oc-london-system-17", "london-system", "London: 6.Bxb8?? and the c-Pawn Promotes", "A45", "d4 Nf6 Bf4 c5 c3 Qb6 Qb3 cxd4 Qxb6 axb6 Bxb8 dxc3 Be5 Rxa2 Rxa2 c2 Kd2 cxb1=Q", 10, ["cxd4"], "b", "After 6.Bxb8, ...dxc3 and ...Rxa2 clear the way for the c-pawn to promote."], ["oc-london-system-18", "london-system", "London Steinitz Countergambit: 8.Qxf5?? Qxb2", "D00", "d4 d5 Bf4 c5 e3 Nc6 c3 Qb6 Qb3 c4 Qc2 e5 dxe5 Bf5 Qxf5 Qxb2", 14, ["Qc1"], "b", "Taking the bishop leaves b2 undefended and ...Qxb2 traps the a1 rook."], ["oc-london-system-19", "london-system", "London 4.Qc2: 9.Nxe5?? Drops a Piece", "A45", "d4 Nf6 Bf4 c5 c3 Qb6 Qc2 cxd4 cxd4 Nc6 e3 d6 Nf3 e5 dxe5 dxe5 Nxe5 Qa5 Nc3 Nxe5 Bxe5 Qxe5", 16, [], "b", "After 9.Nxe5, ...Qa5+ checks and attacks the knight, so Black wins a piece for a pawn."], ["oc-london-system-20", "london-system", "London: 8.Nbd2?? cuts the queen off from d3", "D00", "d4 d5 Bf4 Nc6 e3 Bf5 Nf3 e6 c3 Bd6 Bg3 Nf6 Bd3 Ne4 Nbd2 Nxg3 hxg3 Bxd3", 14, ["Qc2"], "b", "8.Nbd2 blocks the queen's defence of d3, so ...Nxg3 and ...Bxd3 win a piece."], ["oc-ruy-lopez-01", "ruy-lopez", "Rio Gambit: the 5...d5 Overreach", "C67", "e4 e5 Nf3 Nc6 Bb5 Nf6 O-O Nxe4 Re1 d5 d3 Nf6 Nxe5 Be6 Nxc6 bxc6 Bxc6 Nd7 Bxa8 Qxa8", 9, ["Nd6"], "w", "Pushing ...d5 lets d3 chase the knight, then Nxe5 wins a pawn and hits c6."], ["oc-ruy-lopez-02", "ruy-lopez", "Rio Gambit: Grabbing the Bishop Costs the Queen", "C67", "e4 e5 Nf3 Nc6 Bb5 Nf6 O-O Nxe4 Re1 Nd6 Nxe5 Nxb5 Nxc6 Be7 Nxd8 Kxd8", 11, ["Nxe5"], "w", "Taking the bishop opens the e-file, and Nxc6+ discovers check while attacking the queen."], ["oc-ruy-lopez-03", "ruy-lopez", "Spanish Bxf7+ Fork (Qc4+)", "C60", "e4 e5 Nf3 Nc6 Bb5 a6 Ba4 Nf6 Qe2 b5 Bb3 Bc5 a4 b4 Bxf7 Kxf7 Qc4 d5 Qxc5 Qd6 Qxc6 Qxc6 Nxe5 Ke8 Nxc6", 13, ["Na5"], "w", "...b4 allows Bxf7+ and Qc4+ regaining the bishop, then Nxe5+ forks king and queen."], ["oc-ruy-lopez-04", "ruy-lopez", "Bird's Defense Punished (1)", "C60", "e4 e5 Nf3 Nc6 Bb5 Nd4 Nxd4 exd4 O-O c6 Bc4 d5 exd5 cxd5 Bb5 Bd7 Re1 Be7 Qg4 Bxb5 Qxg7 Qd6 Qxh8 O-O-O Qxd4", 19, ["Qc7"], "w", "Taking on b5 leaves g7 open to Qxg7, winning the h8 rook."], ["oc-ruy-lopez-05", "ruy-lopez", "Bird's Defense Punished (2)", "C60", "e4 e5 Nf3 Nc6 Bb5 Nd4 Nxd4 exd4 O-O c6 Bc4 d5 exd5 cxd5 Bb5 Bd7 Re1 Be7 Qg4 Nf6 Qxg7 Rg8 Qxf6 Bxb5 d3 Rg6 Qxd4 Qd6 Qh8 Kd7 Qxa8", 19, [], "w", "Blocking g7 with ...Nf6 runs into the e-file pin, so Qxg7 and Qxf6 win material."], ["oc-ruy-lopez-06", "ruy-lopez", "Rio Gambit: the Pinned f-Pawn Costs a Rook", "C67", "e4 e5 Nf3 Nc6 Bb5 Nf6 O-O Nxe4 Re1 Nd6 Nxe5 Nxe5 Nc3 Nxb5 Rxe5 Be7 Nd5 O-O Nxe7 Kh8 Qh5 g6 Qh4 f6 Nxg6 Kg8 Nxf8 Qxf8 Rxb5", 13, ["Be7"], "w", "Grabbing the b5 bishop allows Nd5 and Qh5; the pinned f6 pawn cannot stop Nxg6+."], ["oc-ruy-lopez-07", "ruy-lopez", "Rio Gambit: Queen Sacrifice, Rh5 Mate", "C67", "e4 e5 Nf3 Nc6 Bb5 Nf6 O-O Nxe4 Re1 Nd6 Nxe5 Nxe5 Nc3 Nxb5 Rxe5 Be7 Nd5 O-O Nxe7 Kh8 Qh5 Nd6 Qxh7 Kxh7 Rh5", 21, ["g6"], "w", "After ...Nd6, the queen sacrifice Qxh7+ and Rh5 is mate; only 11...g6 avoids it."], ["oc-ruy-lopez-08", "ruy-lopez", "Spanish Rh5# (Hastings 1919)", "C60", "e4 e5 Nf3 Nc6 Bb5 a6 Ba4 Nf6 O-O Nxe4 Re1 Nc5 Nc3 Nxa4 Nxe5 Nxe5 Rxe5 Be7 Nd5 O-O Nxe7 Kh8 Qh5 d6 Qxh7 Kxh7 Rh5", 15, ["Be7"], "w", "Recapturing on e5 lets White's pieces race in with Qxh7+ and Rh5#."], ["oc-ruy-lopez-09", "ruy-lopez", "Rio Gambit: Queen Sacrifice Wins a Piece", "C67", "e4 e5 Nf3 Nc6 Bb5 Nf6 O-O Nxe4 Re1 Nd6 Nc3 Nxb5 Nxe5 Nxc3 Nxc6 Be7 Nxe7 Nxd1 Ng6 Qe7 Nxe7 Kd8 Nxc8 Rxc8 Rxd1", 13, ["Nxe5"], "w", "Taking on c3 allows Nxc6+ with discovered check; the knight chain nets a queen and a piece."], ["oc-ruy-lopez-10", "ruy-lopez", "Rio Gambit: Greek Gift on h7", "C67", "e4 e5 Nf3 Nc6 Bb5 Nf6 O-O Nxe4 Re1 Nd6 Nxe5 Nxe5 Nc3 Be7 Rxe5 O-O Bd3 Bf6 Re3 b6 Bxh7 Kxh7 Qh5 Kg8 Rh3 Bh4 Rxh4 f5", 19, ["g6"], "w", "Ignoring the Re3-h3 plan allows Bxh7+ and a queen-and-rook attack; ...g6 covers h5."], ["oc-ruy-lopez-11", "ruy-lopez", "Open Spanish: 10...Be7?? and Qxd5 Forks the Knights", "C80", "e4 e5 Nf3 Nc6 Bb5 a6 Ba4 Nf6 O-O Nxe4 d4 b5 Bb3 d5 dxe5 Be6 a4 b4 a5 Be7 Ba4 Bd7 Qxd5", 19, ["Nc5"], "w", "With d5 undefended after Ba4, Qxd5 forks the e4 and c6 knights."], ["oc-ruy-lopez-12", "ruy-lopez", "Cozio Defense: Nf6# Smothered Mate", "C60", "e4 e5 Nf3 Nc6 Bb5 Nge7 Nc3 g6 d4 exd4 Nd5 a6 Nf6", 11, ["Bg7"], "w", "6...a6 ignores the threat: Nf6# smothers the king; ...Bg7 covers f6."], ["oc-ruy-lopez-13", "ruy-lopez", "Rio Gambit: the Double Pin on g7", "C67", "e4 e5 Nf3 Nc6 Bb5 Nf6 O-O Nxe4 Re1 Nd6 Nxe5 Nxe5 Nc3 f6 d4 Nxb5 dxe5 Nxc3 exf6 Kf7 fxg7 Bxg7 Qh5 Kf8 Bg5 Bf6 Bh6 Bg7 Qe5 Bxh6 Qxh8 Kf7 Qxd8 Nd5", 15, [], "w", "After the weakening ...f6, grabbing the b5 bishop lets White win the g7 bishop and then the h8 rook."], ["oc-ruy-lopez-14", "ruy-lopez", "Tarrasch Trap (Open Ruy Lopez)", "C80", "e4 e5 Nf3 Nc6 Bb5 Nf6 O-O Nxe4 d4 a6 Ba4 b5 Bb3 d5 dxe5 Be6 c3 Be7 Re1 O-O Nd4 Qd7 Nxe6 fxe6 Rxe4", 21, ["Nxe5"], "w", "Qd7 leaves the e4 knight short of defenders; after Nxe6 fxe6 Rxe4 it is lost."], ["oc-ruy-lopez-15", "ruy-lopez", "Noah's Ark Trap", "C71", "e4 e5 Nf3 Nc6 Bb5 a6 Ba4 d6 d4 b5 Bb3 Nxd4 Nxd4 exd4 Qxd4 c5 Qd5 Be6 Qc6 Bd7 Qd5 c4 Bxc4 bxc4", 14, ["c3"], "b", "After 8.Qxd4, ...c5 chases the queen and ...c4 traps the b3 bishop; 8.c3 avoids it."], ["oc-ruy-lopez-16", "ruy-lopez", "Fishing Pole Trap", "C65", "e4 e5 Nf3 Nc6 Bb5 Nf6 O-O Ng4 h3 h5 hxg4 hxg4 Ne1 Qh4 f3 g3 Nd3 Qh1", 10, ["c3", "d4"], "b", "Grabbing on g4 opens the h-file; after ...hxg4 and ...Qh4, the queen mates on h1."], ["oc-ruy-lopez-17", "ruy-lopez", "Schliemann: 7.Ba4?? and the Bishop Falls", "C63", "e4 e5 Nf3 Nc6 Bb5 f5 d4 fxe4 Nxe5 Nxe5 dxe5 c6 Ba4 Qa5 Nc3 Bb4 Bd2 Bxc3 Bxc3 Qxa4", 12, ["Bc4"], "b", "Ba4 puts the bishop on the diagonal of ...Qa5+; retreating to c4 avoids it."], ["oc-ruy-lopez-18", "ruy-lopez", "Spanish: Black ...Nf2# Smother", "C60", "e4 e5 Nf3 Nc6 Bb5 Nf6 O-O Bc5 Re1 Ng4 d4 Nxd4 Nxd4 Qh4 Nf3 Qxf2 Kh1 Qg1 Rxg1 Nf2", 14, [], "b", "After Nf3, ...Qxf2+ and the queen sacrifice on g1 lead to a smothered mate."], ["oc-ruy-lopez-19", "ruy-lopez", "Adams-Wall h-file Mate", "C72", "e4 e5 Nf3 Nc6 Bb5 a6 Ba4 d6 O-O Bg4 h3 h5 Bxc6 bxc6 hxg4 hxg4 Nxe5 Qh4 Nf3 Qh1", 16, ["Re1", "Nh2"], "b", "Greedily taking e5 ignores the open h-file; ...Qh4 threatens Qh1#."], ["oc-caro-kann-defense-01", "caro-kann-defense", "Caro-Kann: Nxf7/Bg6+ Queen Grab", "B10", "e4 c6 Nf3 d5 d3 dxe4 Ng5 exd3 Bxd3 Nf6 Nxf7 Kxf7 Bg6 hxg6 Qxd8", 9, ["Nd7"], "w", "Nf6 lets White sacrifice on f7, then Bg6+ clears d3 and wins the queen."], ["oc-caro-kann-defense-02", "caro-kann-defense", "Caro-Kann Classical Nd6# Trap", "B15", "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Nd7 Qe2 Ngf6 Nd6", 9, ["e6"], "w", "Developing the second knight allows Nd6 smothered mate; ...e6 avoids it."], ["oc-caro-kann-defense-03", "caro-kann-defense", "Caro-Kann: Nxf7/Qf7# Attack", "B10", "e4 c6 Nc3 d5 Nf3 dxe4 Nxe4 Bf5 Ng3 Bg6 h4 h6 Ne5 Bh7 Qh5 g6 Bc4 e6 Qe2 Bg7 Nxf7 Kxf7 Qxe6 Kf8 Qf7", 19, ["Qe7"], "w", "Bg7 ignores the attack on f7 and e6, allowing a sacrifice that ends in Qf7 mate."], ["oc-caro-kann-defense-04", "caro-kann-defense", "Caro-Kann: Bg6# Smother", "B10", "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Nd7 Bd3 Ngf6 Ng5 h6 Ne6 fxe6 Bg6", 11, ["e5", "e6"], "w", "After Ng5, ...h6 allows Ne6 and a smothered mate with Bg6."], ["oc-caro-kann-defense-05", "caro-kann-defense", "Caro-Kann: 5...h6 6.Ne6", "B10", "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Nd7 Ng5 h6 Ne6 Qa5 Bd2 Qb6 Bd3 fxe6 Qh5 Kd8 Ba5 Ngf6 Bxb6 Nxb6 Qe2", 9, ["e6"], "w", "After Ng5, ...h6 allows Ne6 with a fork on d8 that wins the queen."], ["oc-caro-kann-defense-06", "caro-kann-defense", "Caro-Kann: f3 Rxf5/Nxh8", "B10", "e4 c6 d4 d5 Nc3 dxe4 f3 exf3 Nxf3 Bf5 Bc4 e6 O-O Nf6 Ng5 Be7 Rxf5 exf5 Nxf7 Qc7 Nxh8", 15, ["Bg6"], "w", "Be7 ignores the Rxf5 sacrifice, and Nxf7 forks queen and rook."], ["oc-caro-kann-defense-07", "caro-kann-defense", "Caro-Kann: 3...Bg4 Qb5+ trick", "B10", "e4 c6 Nf3 d5 Nc3 Bg4 exd5 cxd5 Qe2 e6 Qb5 Qd7 Ne5 Qxb5 Bxb5 Ke7 Nxg4", 11, ["Nd7", "Nc6"], "w", "Blocking with Qd7 lets Ne5 attack queen and bishop together."], ["oc-caro-kann-defense-08", "caro-kann-defense", "Caro-Kann: 7.Ne5 Nf6? 8.Bd3", "B18", "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Bf5 Ng5 Bg6 N1f3 e6 Ne5 Nf6 Bd3 h6 Bxg6", 13, ["Nd7"], "w", "Nf6 lets Bd3 leave the Bg6 with no good retreat; ...Nd7 challenges the knight first."], ["oc-caro-kann-defense-09", "caro-kann-defense", "Caro-Kann: 8...Qd5?? 9.Nc7+", "B17", "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Nd7 Ng5 Ngf6 Bd3 h6 Ne6 Qa5 Bd2 Qd5 Nc7 Kd8 Nxd5", 15, ["Qb6"], "w", "Qd5 walks into Nc7+, a fork of king and queen."], ["oc-caro-kann-defense-10", "caro-kann-defense", "Caro-Kann: 6...fxe6?? 7.Qh5+", "B17", "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Nd7 Ng5 h6 Ne6 fxe6 Qh5 g6 Qxg6", 11, ["Qb6"], "w", "Capturing on e6 opens the f-file and diagonal, allowing Qh5+ and Qxg6 mate."], ["oc-caro-kann-defense-11", "caro-kann-defense", "Caro-Kann: 7...Qd5?? 8.Nc7+", "B17", "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Nd7 Ng5 h6 Ne6 Qa5 Bd2 Qd5 Nc7 Kd8 Nxd5", 13, ["Qb6"], "w", "Qd5 allows Nc7+, forking king and queen."], ["oc-caro-kann-defense-12", "caro-kann-defense", "Caro-Kann: 7...Qf5?? 8.Nc7+", "B17", "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Nd7 Ng5 h6 Ne6 Qa5 Bd2 Qf5 Nc7 Kd8 Nxa8", 13, ["Qb6"], "w", "Qf5 steps onto the diagonal of the Ne6, so Nc7+ forks king and rook."], ["oc-caro-kann-defense-13", "caro-kann-defense", "Caro-Kann: 10.Ba5! Ngf6?? 11.Bxb6+", "B17", "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Nd7 Ng5 h6 Ne6 Qa5 Bd2 Qb6 Bd3 fxe6 Qh5 Kd8 Ba5 Ngf6 Bxb6", 19, ["g6"], "w", "After Ba5, ...Ngf6 ignores the a5-d8 diagonal and Bxb6+ wins the queen."], ["oc-caro-kann-defense-14", "caro-kann-defense", "Caro-Kann: 11...Nbd5? 12.Ne5", "B15", "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Nf6 Ng5 e6 N1f3 Be7 Bd3 Nbd7 Qe2 Nb6 Bd2 O-O O-O-O h6 h4 Nbd5 Ne5 Nb4 Bxb4", 21, ["Qd5"], "w", "Nbd5 leaves the knight with no stable square after Ne5 and c4."], ["oc-caro-kann-defense-15", "caro-kann-defense", "Caro-Kann: 13.Nf7 Qd5?? 14.Bf4+", "B17", "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Nd7 Ng5 Ngf6 Bd3 e6 N1f3 h6 Nxe6 fxe6 Bg6 Ke7 O-O Nb6 Re1 Kd7 Ne5 Kc7 Nf7 Qd5 Bf4 Kd7 Nxh8 Bd6 Bxd6", 25, ["Qe7"], "w", "Qd5 defends the h8 rook, but Bf4+ drives the king back and Nxh8 wins the rook."], ["oc-caro-kann-defense-16", "caro-kann-defense", "Caro-Kann: 10.f3 Bd5? 11.c4", "B18", "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Bf5 Ng5 e6 N1f3 Be7 h4 Nf6 Ne5 O-O g4 Be4 f3 Bd5 c4 h6 cxd5", 19, ["Bg6"], "w", "Bd5 keeps the bishop in the centre, where c4 attacks it with no safe square left."], ["oc-caro-kann-defense-17", "caro-kann-defense", "Caro-Kann: 13...Bd7? 14.Nf7", "B17", "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Nd7 Ng5 Ngf6 Bd3 e6 N1f3 h6 Nxe6 fxe6 Bg6 Ke7 O-O Nb6 Re1 Nbd5 c4 Nc7 Ne5 Bd7 Nf7 Qb8 Nxh8 Be8 Bf4 Bxg6 Nxg6 Kf7 Nxf8", 25, ["Rg8"], "w", "Bd7 allows Nf7, forking queen and rook, and Nxh8 wins the corner rook."], ["oc-caro-kann-defense-18", "caro-kann-defense", "Caro-Kann: 11...Qxa5+? 12.Qxa5+", "B17", "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Nd7 Ng5 h6 Ne6 Qa5 Bd2 Qb6 Bd3 fxe6 Qh5 g6 Bxg6 Kd8 Ba5 Qxa5 Qxa5", 21, [], "w", "Qxa5+ looks safe, but the check answers back and trades queens, leaving White a clean exchange up."], ["oc-caro-kann-defense-19", "caro-kann-defense", "Caro-Kann: 15...c5? 16.Nh7", "B15", "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Nf6 Ng5 e6 N1f3 Be7 Bd3 Nbd7 Qe2 Nb6 Bd2 O-O O-O-O Nbd5 c4 Nb4 Bb1 a5 a3 Na6 h4 h6 Qd3 c5 Nh7 Re8 Nxf6", 29, [], "w", "c5 opens the c-file too slowly; Nh7 hits the f6 knight and the kingside collapses first."], ["oc-caro-kann-defense-20", "caro-kann-defense", "Caro-Kann: 23...Qe7? 24.Qh7+", "B15", "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Nf6 Ng5 e6 N1f3 Be7 Bd3 O-O O-O Nbd7 Re1 h6 Ne4 Nxe4 Bxe4 Nf6 Bd3 Nd5 c4 Nf6 Bf4 b6 Ne5 c5 Qf3 Ba6 d5 Bb7 Bxh6 gxh6 Qh3 Kg7 Re3 exd5 Rg3 Ng4 Qxg4 Bg5 Qf5 Qe7 Qh7 Kf6 Rxg5 Qe6 Qg7 Ke7 Rg6 Bc8 cxd5 Rg8 Rxe6", 45, [], "w", "After the h6 sacrifice, Qe7 defends too slowly; Qh7+ and Rxg5 keep the attack going."], ["oc-caro-kann-defense-21", "caro-kann-defense", "Caro-Kann: 14...Qxe5?? 15.Bb6+", "B17", "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Nd7 Ng5 Ngf6 Bd3 e6 N1f3 h6 Nxe6 fxe6 Bg6 Ke7 O-O Qc7 Re1 Kd8 Ne5 Nxe5 dxe5 Nd7 Be3 Qxe5 Bb6 axb6 Rxe5", 27, [], "w", "Qxe5 puts the queen on the a5-d8 diagonal, and Bb6+ deflects it."], ["oc-caro-kann-defense-22", "caro-kann-defense", "Caro-Kann: 17.Ng4 Be4? 18.Nxf6+", "B15", "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Nf6 Ng5 e6 N1f3 Bd6 Bd3 h6 Ne4 Nxe4 Bxe4 Nd7 c3 Nf6 Bc2 O-O O-O Qc7 h3 b6 Re1 Bb7 Ne5 c5 Qd3 cxd4 Ng4 Be4 Nxf6 gxf6 Rxe4 f5 Rg4 Kh8 Bxh6 f6 Rxd4", 33, [], "w", "Be4 offers a trade, but Nxf6+ opens the king first and the attack rolls on."], ["oc-caro-kann-defense-23", "caro-kann-defense", "Caro-Kann: 16...Be8? 17.c5", "B17", "e4 c6 d4 d5 Nc3 dxe4 Nxe4 Nd7 Ng5 Ngf6 Bd3 e6 N1f3 h6 Nxe6 fxe6 Bg6 Ke7 O-O Qc7 Re1 Nb6 Ne5 Bd7 Bf4 Nbd5 Bg3 Qb6 c4 Nb4 a3 Be8 c5 Qb5 axb4 Qxb4 Bxe8 Rxe8 Rxa7 Rd8 Nxc6 Kf7 Nxb4 Bxc5 Rxb7 Rd7 Rxd7", 31, [], "w", "Be8 offers a trade too late; c5 attacks queen and knight at once."], ["oc-caro-kann-defense-24", "caro-kann-defense", "Caro-Kann Advance: 8...Nge7? The Greek Gift", "B12", "e4 c6 d4 d5 e5 e6 Nf3 c5 c3 cxd4 cxd4 Nc6 Nc3 Bb4 Bd3 Nge7 O-O O-O Bxh7 Kxh7 Ng5 Kg6 Ne2 Nf5 Nf4 Kh6 Qh5", 15, ["Nh6"], "w", "Nge7 allows a Bxh7+ sacrifice after castling, ending in Qh5 mate."], ["oc-caro-kann-defense-25", "caro-kann-defense", "Caro-Kann: mate on f7 with the knight on e5", "B10", "e4 c6 Nc3 d5 Nf3 dxe4 Nxe4 Bf5 Ng3 Bg6 h4 h5 Ne5 Bh7 Qxh5 Nf6 Qxf7", 15, ["Nh6", "g6"], "w", "After Qxh5, ...Nf6 leaves f7 unguarded and Qxf7 is mate."], ["oc-caro-kann-defense-26", "caro-kann-defense", "Caro-Kann: 8...Qd5? 9.Bc4", "B10", "e4 c6 Nc3 d5 Nf3 dxe4 Nxe4 Bf5 Ng3 Bg6 h4 h6 Ne5 Bh7 Qh5 Qd5 Bc4 Nf6 Bxd5 Nxh5 Bxf7 Kd8 Bxh5 Kc7 Bg6 Nd7 Bxh7", 15, ["g6"], "w", "Qd5 ties the queen to defending f7, and Bc4 attacks that square."], ["oc-caro-kann-defense-27", "caro-kann-defense", "Caro-Kann: 9...e6? 10.Bf4", "B11", "e4 c6 Nc3 d5 Nf3 Bg4 h3 Bh5 exd5 cxd5 Bb5 Nc6 g4 Bg6 Ne5 Qd6 d4 e6 Bf4 Ne7 Nxg6 Qb4 Nxh8", 17, ["f6", "a6"], "w", "...e6 allows Bf4, and Ne5 moves with a discovered attack on the queen."], ["oc-caro-kann-defense-28", "caro-kann-defense", "Caro-Kann: 9...Qd5? 10.Qxd5 cxd5 11.Bb5+", "B10", "e4 c6 Nc3 d5 Nf3 dxe4 Nxe4 Bf5 Ng3 Bg6 h4 h6 Ne5 Bh7 Qh5 g6 Qf3 Qd5 Qxd5 cxd5 Bb5 Nc6 Nxc6", 17, ["Nf6"], "w", "Offering a queen trade lets the recapture open the b5-e8 diagonal, and the pinned knight falls."], ["oc-sicilian-defense-01", "sicilian-defense", "Dragon: 5...g6?? and the e6 Wedge", "B33", "e4 c5 Nf3 Nc6 d4 cxd4 Nxd4 Nf6 Nc3 g6 Nxc6 bxc6 e5 Nd5 Nxd5 cxd5 Qxd5 Rb8 e6 fxe6 Qe5 Rb6 Qxh8", 9, ["d6"], "w", "5...g6 allows Nxc6 and e5 with tempo; 5...d6 closes the diagonal."], ["oc-sicilian-defense-02", "sicilian-defense", "Levenfish Dragon: 7...dxe5?? Loses a Knight", "B71", "e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 g6 f4 Bg7 e5 dxe5 fxe5 Ng4 Bb5 Bd7 Qxg4", 13, ["Nh5"], "w", "7...dxe5 drops a knight to 8.fxe5 and Bb5+; 7...Nh5 is safe."], ["oc-sicilian-defense-03", "sicilian-defense", "Smith-Morra: Bxf7+/Qf5# Mate", "B20", "e4 c5 d4 cxd4 Nf3 e5 c3 dxc3 Nxc3 d6 Bc4 h6 Bxf7 Kxf7 Nxe5 Ke8 Qh5 Ke7 Nd5 Ke6 Qf5", 11, ["Nc6", "Nf6"], "w", "6...h6 wastes a tempo; 7.Bxf7+ and 8.Nxe5+ lead to Qf5 mate."], ["oc-sicilian-defense-04", "sicilian-defense", "Delayed Alapin: the Same Qa4+ Trick after 4.h3", "B50", "e4 c5 Nf3 d6 c3 Nf6 h3 Nxe4 Qa4 Nc6 Qxe4", 7, ["Nc6"], "w", "4...Nxe4 allows 5.Qa4+ and the knight falls; 4...Nc6 develops first."], ["oc-sicilian-defense-05", "sicilian-defense", "Sveshnikov: 9...a6?? and Nxd6#", "B33", "e4 c5 Nf3 Nc6 d4 cxd4 Nxd4 Nf6 Nc3 e5 Ndb5 d6 Nd5 Nxd5 exd5 Ne7 c4 a6 Qa4 Bd7 Nxd6", 17, ["Ng6"], "w", "9...a6 allows 10.Qa4 and 11.Nxd6 mate; 9...Ng6 frees the bishop to guard d6."], ["oc-sicilian-defense-06", "sicilian-defense", "Alapin: 4...Nxe4?? and the Qa4+ Fork", "B22", "e4 c5 c3 d6 d4 Nf6 dxc5 Nxe4 Qa4 Nc6 Qxe4", 7, ["Nc6"], "w", "4...Nxe4 loses to the Qa4+ check and a fork on e4."], ["oc-sicilian-defense-07", "sicilian-defense", "Dragon: 6...Ng4?? 7.Bb5+", "B20", "e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 g6 Be3 Ng4 Bb5 Nc6 Nxc6 bxc6 Bxc6 Bd7 Bxa8", 11, ["Bg7"], "w", "6...Ng4 loses to the 7.Bb5+ zwischenzug; 6...Bg7 is correct."], ["oc-sicilian-defense-08", "sicilian-defense", "Sveshnikov: 9...Qxf6?? and the Queen Hunt", "B33", "e4 c5 Nf3 Nc6 d4 cxd4 Nxd4 Nf6 Nc3 e5 Ndb5 d6 Bg5 a6 Na3 b5 Bxf6 Qxf6 Nd5 Qd8 Bxb5 axb5 Nxb5 Qa5 c3 Qxb5 Nc7 Kd8 Nxb5", 17, ["gxf6"], "w", "9...Qxf6 allows 10.Nd5 and a queen hunt; 9...gxf6 is the main line."], ["oc-sicilian-defense-09", "sicilian-defense", "Smith-Morra: 6.e5 dxe5?? Bxf7+ Queen Grab", "B21", "e4 c5 d4 cxd4 c3 dxc3 Nxc3 d6 Bc4 Nf6 e5 dxe5 Bxf7 Kxf7 Qxd8", 11, ["Nfd7", "Nd5"], "w", "6...dxe5 opens the d-file to 7.Bxf7+ and 8.Qxd8."], ["oc-sicilian-defense-10", "sicilian-defense", "Smith-Morra: Nb5/Nd6# Mate", "B20", "e4 c5 d4 cxd4 c3 dxc3 Nxc3 Nc6 Nf3 e6 Bc4 Nge7 Bg5 h6 Nb5 hxg5 Nd6", 13, ["a6"], "w", "7...h6 ignores 8.Nb5 and the Nd6 smother mate; 7...a6 denies b5."], ["oc-sicilian-defense-11", "sicilian-defense", "Dragon: 8...dxe5?? Bxf7+/Qxd8", "B20", "e4 c5 Nf3 Nc6 d4 cxd4 Nxd4 Nf6 Nc3 d6 Bc4 g6 Nxc6 bxc6 e5 dxe5 Bxf7 Kxf7 Qxd8", 15, ["Nd7"], "w", "8...dxe5 allows 9.Bxf7+ and 10.Qxd8; 8...Nd7 holds material."], ["oc-sicilian-defense-12", "sicilian-defense", "Alapin: Bg4/...Bxd1 Material", "B20", "e4 c5 Nf3 d6 c3 Nc6 d4 cxd4 cxd4 Bg4 d5 Ne5 Nxe5 Bxd1 Bb5 Qd7 Bxd7 Kd8 Nxf7 Kxd7 Kxd1 Nf6 Nxh8", 11, ["Nb8", "Nb4"], "w", "...Bxd1 falls to Bb5+ and Nxf7; the knight should have retreated on move six."], ["oc-sicilian-defense-13", "sicilian-defense", "Najdorf: the Bxe6 Sacrifice after 8...b5", "B96", "e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 a6 Bg5 e6 f4 Nbd7 Bc4 b5 Bxe6 fxe6 Nxe6 Qa5 Nxf8 Rxf8 Qxd6", 15, ["Be7"], "w", "8...b5 allows the Bxe6 sacrifice; 8...Be7 and castling first avoids it."], ["oc-sicilian-defense-14", "sicilian-defense", "Closed Sicilian: 6...d5?? and the Pinned f7 Pawn", "B23", "e4 c5 Nc3 Nc6 Bb5 Nd4 Bc4 e6 Nf3 Nf6 O-O d5 exd5 exd5 Nxd5 Nxd5 Nxd4 cxd4 Qh5 Be6 Re1 Nc7 Bxe6 Nxe6 Rxe6", 11, ["a6"], "w", "6...d5 allows exd5 and Qh5 pinning f7; 6...a6 kicks the bishop first."], ["oc-sicilian-defense-15", "sicilian-defense", "Alapin: ...Qa5+?? Bb5# Mate", "B20", "e4 c5 Nf3 d6 c3 Nc6 d4 cxd4 cxd4 Bg4 d5 Ne5 Nxe5 Qa5 Bd2 Bxd1 Bxa5 dxe5 Bb5", 13, [], "w", "7...Qa5+ fails to 8.Bd2 and Bb5 mate."], ["oc-sicilian-defense-16", "sicilian-defense", "Accelerated Dragon: King Hunt from f7 to h5", "B35", "e4 c5 Nf3 Nc6 d4 cxd4 Nxd4 g6 Nc3 Bg7 Be3 Nf6 Bc4 O-O Bb3 Na5 e5 Ne8 Bxf7 Kxf7 Ne6 Kxe6 Qd5 Kf5 g4 Kxg4 Rg1 Kh4 Bg5 Kh5 Qd1 Rf3 Qxf3", 19, ["Kh8"], "w", "10...Kxf7 walks into Ne6 and a king hunt to h5; 10...Kh8 declines."], ["oc-sicilian-defense-17", "sicilian-defense", "Smith-Morra: 6...Na5?? and Bxf7+ Wins the Queen", "B21", "e4 c5 d4 cxd4 c3 dxc3 Nxc3 Nc6 Nf3 g6 Bc4 Na5 Bxf7 Kxf7 Qd4 Bg7 Ng5 Kf8 Ne6 dxe6 Qxd8", 11, ["Bg7"], "w", "6...Na5 allows Bxf7+ and Qd4 with Ng5 forks; 6...Bg7 finishes development first."], ["oc-sicilian-defense-18", "sicilian-defense", "Najdorf: 10...Qb6?? and the Qxe7# Finish", "B96", "e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 a6 Bg5 e6 f4 Nbd7 Bc4 b5 Bxe6 fxe6 Nxe6 Qb6 Nd5 Nxd5 Qxd5 Bb7 Nc7 Qxc7 Qe6 Be7 Qxe7", 19, ["Qa5"], "w", "10...Qb6 allows Nd5, Nc7+ and Qxe7 mate; 10...Qa5 avoids the diagonal trap."], ["oc-sicilian-defense-19", "sicilian-defense", "Kalashnikov: 9...Rb8?? and Qxf5# in Four", "B32", "e4 c5 Nf3 Nc6 d4 cxd4 Nxd4 e5 Nb5 d6 N1c3 Nf6 Bg5 h6 Bxf6 gxf6 Nd5 Rb8 Nbc7 Kd7 Qg4 f5 Qxf5", 17, [], "w", "9...Rb8 walks into Nbc7+ and Qg4+, then Qxf5 mate."], ["oc-sicilian-defense-20", "sicilian-defense", "Rossolimo: 6...Qxb5?? and Nc7+ Forks", "B30", "e4 c5 Nf3 Nc6 Bb5 Qb6 Nc3 Nd4 Nxd4 cxd4 Nd5 Qxb5 Nc7 Kd8 Nxb5", 11, ["Qd8"], "w", "6...Qxb5 allows Nc7+ forking king and rook, then Nxb5."], ["oc-sicilian-defense-21", "sicilian-defense", "Kalashnikov: 9...Be6?? Drops the Rook", "B32", "e4 c5 Nf3 Nc6 d4 cxd4 Nxd4 e5 Nb5 d6 N1c3 Nf6 Bg5 h6 Bxf6 gxf6 Nd5 Be6 Nbc7 Kd7 Nxa8", 17, ["a6"], "w", "9...Be6 misses the Nbc7+ fork on the a8 rook."], ["oc-sicilian-defense-22", "sicilian-defense", "Kan: the Nb6 Raid Traps the Rook", "B43", "e4 c5 Nf3 e6 d4 cxd4 Nxd4 a6 Nc3 g6 Be3 Bg7 Nb3 Ne7 Na4 d5 Nb6 Ra7 exd5 exd5 Nxc8 Qxc8 Bxa7", 13, ["Nc6"], "w", "7...Ne7 lets Na4-b6 hit the rook; 7...Nc6 keeps b6 covered."], ["oc-sicilian-defense-23", "sicilian-defense", "Sicilian Declined: d5/Ne5 Nxd7", "B20", "e4 c5 Nf3 Nc6 d4 e6 d5 exd5 exd5 Nce7 Ne5 d6 Bb5 Bd7 Bxd7 Qxd7 Nxd7", 11, ["Ng6"], "w", "6...d6 allows Bb5+ and Nxd7 after the queen trade."], ["oc-sicilian-defense-24", "sicilian-defense", "Nimzowitsch Sicilian: 6...Nxc3?? Costs the Rook", "B29", "e4 c5 Nf3 Nf6 Nc3 d5 exd5 Nxd5 Bb5 Bd7 Ne5 Nxc3 dxc3 Bxb5 Qxd8 Kxd8 Nxf7 Ke8 Nxh8", 11, ["Bxb5"], "w", "Early Nxc3 allows dxc3 and a queen trade, then Nxf7+ forks king and rook."], ["oc-sicilian-defense-25", "sicilian-defense", "Nimzowitsch Sicilian: 7...f6?? and Qxg6#", "B29", "e4 c5 Nf3 Nf6 Nc3 d5 exd5 Nxd5 Bb5 Bd7 Ne5 Nxc3 Qf3 f6 Qh5 g6 Nxg6 hxg6 Qxg6", 13, ["Qc7"], "w", "Weakening with ...f6 walks into Qh5+ and a sacrifice on g6 that mates."], ["oc-sicilian-defense-26", "sicilian-defense", "Sicilian: ...Qxa1?? Nb3 Queen Trap", "B20", "e4 c5 Nf3 e6 d4 cxd4 Nxd4 Nf6 Nc3 Bb4 e5 Nd5 Qg4 g6 a3 Qa5 axb4 Qxa1 Nb3", 15, ["Bxc3"], "b", "Qxa1 wins a rook but Nb3 traps the queen; 8...Bxc3+ is the honest alternative."], ["oc-sicilian-defense-27", "sicilian-defense", "Chekhover: 5...b5?? and the Qd5 Double Attack", "B53", "e4 c5 Nf3 d6 d4 cxd4 Qxd4 a6 Be3 b5 Qd5 Ra7 Qxb5", 9, ["Nc6"], "w", "...b5 lets Qd5 hit both the a8 rook and b5 pawn."], ["oc-sicilian-defense-28", "sicilian-defense", "Alapin: the Wandering Knight and Qxf7#", "B22", "e4 c5 c3 Nf6 e5 Nd5 Bc4 Nf4 Qf3 Ng6 Qxf7", 9, ["Ne6"], "w", "...Ng6 opens the diagonal so Qxf7 mates; ...Ne6 holds f7."], ["oc-sicilian-defense-29", "sicilian-defense", "Najdorf: 11...gxf4?? and the Bh4 Interference", "B96", "e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 a6 Bg5 e6 f4 Nc6 Nxc6 bxc6 e5 h6 Bh4 g5 Bg3 gxf4 Bh4 dxe5 Qxd8 Kxd8 Bxf6 Ke8 Bxh8", 21, ["Nd5"], "w", "Grabbing on f4 lets Bh4 return and pin the f6 knight."], ["oc-sicilian-defense-30", "sicilian-defense", "Smith-Morra: Nd5/Rxc7 Rout", "B20", "e4 c5 d4 cxd4 c3 dxc3 Nxc3 e6 Nf3 a6 Bc4 Nc6 O-O Qc7 Qe2 d6 Rd1 Be7 Be3 Nf6 Rac1 Bd7 Nd5 exd5 exd5 Ne5 Nxe5 dxe5 d6 Bxd6 Bxf7 Kxf7 Rxc7", 27, ["Qd8"], "w", "Recapturing dxe5 reopens the bishop's diagonal and the c-file pin."], ["oc-sicilian-defense-31", "sicilian-defense", "Richter-Rauzer: 8...Bc8?? and Qxf5#", "B60", "e4 c5 Nf3 Nc6 d4 cxd4 Nxd4 Nf6 Nc3 d6 Bg5 Bd7 Be2 e5 Ndb5 Bc8 Nd5 Rb8 Nbc7 Kd7 Bg4 Nxg4 Qxg4 f5 Qxf5", 15, ["Be6"], "w", "Bc8 wastes time: Nd5, Nc7+ and Bg4+ sacrifices mate on f5."], ["oc-sicilian-defense-32", "sicilian-defense", "Smith-Morra: 9...Nh5?? and Qxf7#", "B21", "e4 c5 d4 cxd4 c3 dxc3 Nxc3 Nc6 Nf3 g6 Bc4 Na5 Qd4 Nf6 e5 Nc6 Qf4 Nh5 Qxf7", 17, [], "w", "Nh5 hits the queen but removes the last defender of f7, and Qxf7 mates."], ["oc-sicilian-defense-33", "sicilian-defense", "Chekhover: 11...Qxe5?? and Qd8#", "B53", "e4 c5 Nf3 d6 d4 cxd4 Qxd4 a6 Be3 Nf6 Nc3 Nc6 Qd2 e6 O-O-O Qc7 Bf4 Ne5 Nxe5 dxe5 Bxe5 Qxe5 Qd8", 21, ["Qa5"], "w", "Qxe5 leaves d8 undefended against the rook; Qa5 keeps the defence."], ["oc-sicilian-defense-34", "sicilian-defense", "Sicilian 2.d4 d5: the Nd6# Smother", "B21", "e4 c5 d4 d5 Nc3 dxe4 Nxe4 Nd7 Qe2 Ngf6 Nd6", 9, ["e6", "Nb6"], "w", "Ngf6 allows Nd6# with the king boxed in; e6 or Nb6 gives it air."], ["oc-sicilian-defense-35", "sicilian-defense", "Closed Sicilian: 9...b5?? leaves c6 without a guard", "B26", "e4 c5 Nc3 Nc6 g3 g6 Bg2 Bg7 d3 d6 Be3 Nf6 h3 O-O Qd2 a6 Bh6 b5 Bxg7 Kxg7 e5 Nxe5 Bxa8", 17, ["Nd4", "Rb8"], "w", "After ...b5, Bxg7 and e5 win the rook on a8."], ["oc-sicilian-defense-36", "sicilian-defense", "O'Kelly: 6.Nf5?? and the ...d5 Counterblow", "B28", "e4 c5 Nf3 a6 d4 cxd4 Nxd4 Nf6 Nc3 e5 Nf5 d5 Nxd5 Nxd5 exd5 Bxf5", 10, ["Nb3"], "b", "Nf5 hangs the knight to ...d5, which opens the centre and lets Bxf5 win a piece."], ["oc-sicilian-defense-37", "sicilian-defense", "Accelerated Dragon: 8.f3?? and ...Qb6 Wins a Piece", "B35", "e4 c5 Nf3 g6 d4 Bg7 Nc3 cxd4 Nxd4 Nc6 Be3 Nf6 Bc4 O-O f3 Qb6 Nxc6 Qxe3 Qe2 Qxe2 Bxe2 dxc6", 14, ["Bb3"], "b", "f3 leaves e3 defended only by the queen; ...Qb6 double-attacks e3 and b2."], ["oc-sicilian-defense-38", "sicilian-defense", "Kan Sicilian: 7.Qd2?? and the ...d5 Break Wins a Pawn", "B43", "e4 c5 Nf3 e6 d4 cxd4 Nxd4 a6 Nc3 Qc7 Be3 Bb4 Qd2 Nf6 f3 d5 Nb3 dxe4 fxe4 Nxe4", 12, ["Bd2"], "b", "Qd2 leaves the c3 knight pinned, so ...d5 and ...Nxe4 win a pawn."], ["oc-sicilian-defense-39", "sicilian-defense", "Rossolimo: 4.Ba4?? and the Noah's Ark Motif", "B30", "e4 c5 Nf3 Nc6 Bb5 a6 Ba4 b5 Bb3 c4 Bxc4 bxc4", 6, ["Bxc6"], "b", "Ba4 is a Ruy Lopez reflex; after ...b5 and ...c4 the bishop has no squares."], ["oc-sicilian-defense-40", "sicilian-defense", "Wing Gambit: 5.axb4?? and the Qe5+ Fork", "B20", "e4 c5 b4 cxb4 a3 d5 exd5 Qxd5 axb4 Qe5 Be2 Qxa1", 8, ["Nf3", "Bb2"], "b", "axb4 allows ...Qe5+ hitting the king and the a1 rook."], ["oc-sicilian-defense-41", "sicilian-defense", "Siberian Trap", "B21", "e4 c5 d4 cxd4 c3 dxc3 Nxc3 Nc6 Nf3 e6 Bc4 Qc7 O-O Nf6 Qe2 Ng4 h3 Nd4 Nxd4 Qh2", 16, ["Nb5"], "b", "After ...Ng4, h3 allows ...Nd4 and ...Qxh2 mate; Nb5 hits the queen instead."], ["oc-sicilian-defense-42", "sicilian-defense", "Kan Sicilian: the ...e5 Fork", "B42", "e4 c5 Nf3 e6 d4 cxd4 Nxd4 a6 Bf4 e5 Bxe5 Qa5 Nc3 Qxe5", 10, ["Bg3"], "b", "Bf4 allows ...e5 forking bishop and knight; grabbing on e5 loses to ...Qa5+."], ["oc-sicilian-defense-43", "sicilian-defense", "Grand Prix Attack: 8.d3?? and the Qa5+ Skewer", "B23", "e4 c5 Nc3 Nc6 f4 g6 Nf3 Bg7 Bb5 Nd4 Nxd4 cxd4 Ne2 e6 d3 Qa5 Bd2 Qxb5", 14, ["a4", "Bc4"], "b", "d3 opens the d8-a5 diagonal while the b5 bishop is undefended."], ["oc-sicilian-defense-44", "sicilian-defense", "Alapin: 7.Qa4+?? Loses the Bishop", "B22", "e4 c5 c3 d5 exd5 Qxd5 d4 e6 Nf3 Nf6 Bd3 c4 Qa4 b5 Qd1 cxd3", 12, ["Be2"], "b", "A check doesn't save the attacked bishop: ...b5 blocks and defends c4, then ...cxd3."], ["oc-sicilian-defense-45", "sicilian-defense", "Closed Sicilian: 6.g3?? and Nf3#", "B23", "e4 c5 Nc3 Nc6 Nge2 g6 d3 Bg7 Be3 Nd4 g3 Nf3", 10, ["h4", "Nxd4"], "b", "With a knight on d4, g3 leaves f3 uncovered and ...Nf3 is mate."], ["oc-sicilian-defense-46", "sicilian-defense", "Staunton-Cochrane: 5.g3?? and Nd3#", "B20", "e4 c5 c4 Nc6 Ne2 Nf6 Nbc3 Nb4 g3 Nd3", 8, ["d4"], "b", "After ...Nb4, g3 allows ...Nd3#, a square nobody controls."]];
